WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'amari' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'amari');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: amari', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'あまり' AND DATALENGTH(c.Pattern) = DATALENGTH(N'あまり') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'あまり' AND DATALENGTH(c.Reading) = DATALENGTH(N'あまり') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Vì quá… nên', Formation = N'Danh từ ＋ のあまり／động từ thể thường ＋ あまり', Explanation = N'Cảm xúc hoặc trạng thái quá mạnh dẫn đến một phản ứng, thường ngoài ý muốn.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'so much ~ that; out of an excess of (a feeling)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'so much ~ that; out of an excess of (a feeling)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun＋の＋あまり
Verb［plain form］＋あまり' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun＋の＋あまり
Verb［plain form］＋あまり') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜のあまり (after a noun of feeling) or 〜あまり (after a verb) means an emotion or state was so extreme that it caused the result that follows — 緊張のあまり = out of too much nervousness, 心配のあまり = from worrying too much. It presents an overpowering cause leading to an often unexpected or unwanted outcome.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜のあまり (after a noun of feeling) or 〜あまり (after a verb) means an emotion or state was so extreme that it caused the result that follows — 緊張のあまり = out of too much nervousness, 心配のあまり = from worrying too much. It presents an overpowering cause leading to an often unexpected or unwanted outcome.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'This あまり (''so much that'') usually follows a feeling-noun + の or a verb; it is not the adverb あまり〜ない (''not very''), which needs a negative verb.
It tends to introduce an extreme cause and a striking or negative consequence, not a neutral ''because''.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'This あまり (''so much that'') usually follows a feeling-noun + の or a verb; it is not the adverb あまり〜ない (''not very''), which needs a negative verb.
It tends to introduce an extreme cause and a striking or negative consequence, not a neutral ''because''.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Tôi vui quá đến bật khóc.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'amari:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'amari:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'うれしさのあまり、涙が出てしまいました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'うれしさのあまり、涙が出てしまいました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Tôi căng thẳng đến mức nói nhầm tên mình.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'amari:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'amari:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'緊張のあまり、自分の名前を言い間違えました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'緊張のあまり、自分の名前を言い間違えました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N3-G-002.json: amari-ni-mo
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'amari-ni-mo' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'amari-ni-mo');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: amari-ni-mo', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'あまりに・あまりにも' AND DATALENGTH(c.Pattern) = DATALENGTH(N'あまりに・あまりにも') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'あまりに・あまりにも' AND DATALENGTH(c.Reading) = DATALENGTH(N'あまりに・あまりにも') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Quá, đến mức', Formation = N'あまりに／あまりにも ＋ từ chỉ mức độ, đặc điểm hoặc trạng thái', Explanation = N'Nhấn mạnh mức độ vượt xa bình thường và có thể dẫn tới kết quả ở vế sau.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'excessively; far too; so ~ (that)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'excessively; far too; so ~ (that)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'あまりに（も）＋ い-adjective ／ な-adjective ／ Verb' AND DATALENGTH(c.Formation) = DATALENGTH(N'あまりに（も）＋ い-adjective ／ な-adjective ／ Verb') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'あまりに and あまりにも are adverbs placed directly before an adjective or verb to say something is excessive — ''far too ~''. あまりにも高い = far too expensive, あまりに忙しい = terribly busy. The も is optional and just strengthens the emphasis. It often leads into a result: ''so ~ that…''.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'あまりに and あまりにも are adverbs placed directly before an adjective or verb to say something is excessive — ''far too ~''. あまりにも高い = far too expensive, あまりに忙しい = terribly busy. The も is optional and just strengthens the emphasis. It often leads into a result: ''so ~ that…''.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'あまりに（も）is an adverb and goes in front of the word it intensifies; it does not follow a noun the way 〜のあまり does.
The も is optional — あまりに and あまりにも mean the same thing, with も adding a touch more emphasis.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'あまりに（も）is an adverb and goes in front of the word it intensifies; it does not follow a noun the way 〜のあまり does.
The も is optional — あまりに and あまりにも mean the same thing, with も adding a touch more emphasis.');
SET @Parents += @@ROWCOUNT;
