-- N3-G-002.json: ari
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'ari' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'ari');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ari', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'〜あり' AND DATALENGTH(c.Pattern) = DATALENGTH(N'〜あり') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'あり' AND DATALENGTH(c.Reading) = DATALENGTH(N'あり') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Có, có kèm', Formation = N'Danh từ ＋ あり／ありで', Explanation = N'Cho biết một thứ hoặc điều kiện có sẵn. わけあり là cách nói cố định chỉ hàng có lý do đặc biệt, chẳng hạn bị lỗi nhẹ.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'with ~; having ~; ~ included' AND DATALENGTH(c.Meaning) = DATALENGTH(N'with ~; having ~; ~ included') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun＋あり' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun＋あり') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜あり is a noun-like suffix built from ある that labels something as ''having ~'' or ''with ~'' — 駐車場あり = parking available, わけあり = with (special) circumstances. You see it on notices, listings, and menus. Its opposite is 〜なし (''without ~'').' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜あり is a noun-like suffix built from ある that labels something as ''having ~'' or ''with ~'' — 駐車場あり = parking available, わけあり = with (special) circumstances. You see it on notices, listings, and menus. Its opposite is 〜なし (''without ~'').') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Here あり is a fixed label, not the conjugating verb ある; it sits at the end like a noun (エアコンあり).
It is common in written, sign-style Japanese; in full sentences you would normally say ～がある instead.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Here あり is a fixed label, not the conjugating verb ある; it sits at the end like a noun (エアコンあり).
It is common in written, sign-style Japanese; in full sentences you would normally say ～がある instead.');
SET @Parents += @@ROWCOUNT;
