AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'ari:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'ari:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'このアパートはエアコンありで、すぐに住めます。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'このアパートはエアコンありで、すぐに住めます。')
