IF @Matches > 1 THROW 51001, 'Ambiguous translation source: aruiwa', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'あるいは' AND DATALENGTH(c.Pattern) = DATALENGTH(N'あるいは') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'あるいは' AND DATALENGTH(c.Reading) = DATALENGTH(N'あるいは') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Hoặc, hoặc cũng có thể', Formation = N'A ＋ あるいは ＋ B', Explanation = N'Nối các lựa chọn hoặc khả năng. Thường gặp trong cách nói hay văn viết trang trọng.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'or; or else; alternatively; possibly' AND DATALENGTH(c.Meaning) = DATALENGTH(N'or; or else; alternatively; possibly') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun＋あるいは＋Noun
Sentence。あるいは、Sentence' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun＋あるいは＋Noun
Sentence。あるいは、Sentence') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'あるいは joins two options (''A あるいは B'' = A or B) and can also work as an adverb meaning ''possibly / perhaps'', often with かもしれない. It is fairly formal and belongs to written or careful spoken Japanese. Between choices it functions like または; as ''perhaps'' it flags one uncertain possibility.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'あるいは joins two options (''A あるいは B'' = A or B) and can also work as an adverb meaning ''possibly / perhaps'', often with かもしれない. It is fairly formal and belongs to written or careful spoken Japanese. Between choices it functions like または; as ''perhaps'' it flags one uncertain possibility.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'あるいは is on the formal, written side; in casual speech または (between choices) or それとも (in questions) sound more natural.
In its ''perhaps'' meaning it often pairs with かもしれない to mark one uncertain possibility.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'あるいは is on the formal, written side; in casual speech または (between choices) or それとも (in questions) sound more natural.
In its ''perhaps'' meaning it often pairs with かもしれない to mark one uncertain possibility.');
