UPDATE c SET Meaning = N'Trong khi, mặt khác', Formation = N'Mệnh đề bổ nghĩa ＋ 一方で', Explanation = N'Đặt cạnh hai mặt khác nhau của một việc hoặc đối chiếu hai chủ thể.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'on one hand ~, on the other hand ~; while' AND DATALENGTH(c.Meaning) = DATALENGTH(N'on one hand ~, on the other hand ~; while') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb ／ い-adjective［plain form］＋一方（で）
