-- N3-G-005.json: gatai
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'gatai' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'gatai');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: gatai', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'がたい' AND DATALENGTH(c.Pattern) = DATALENGTH(N'がたい') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'がたい' AND DATALENGTH(c.Reading) = DATALENGTH(N'がたい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Khó mà làm, khó lòng', Formation = N'Gốc ます ＋ がたい', Explanation = N'Nhấn mạnh cái khó đến mức gần như không thể, thường khi tin, chấp nhận hoặc quên một điều.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'hard to bring oneself to; difficult (almost impossible) to do' AND DATALENGTH(c.Meaning) = DATALENGTH(N'hard to bring oneself to; difficult (almost impossible) to do') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ がたい' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ がたい') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜がたい attaches to the ます-stem and marks an action as hard, sometimes nearly impossible, to do — 信じがたい = hard to believe, 忘れがたい = unforgettable. It is formal and rather literary, and pairs with a limited set of verbs of thinking, feeling, and perception. The whole compound behaves like an い-adjective.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜がたい attaches to the ます-stem and marks an action as hard, sometimes nearly impossible, to do — 信じがたい = hard to believe, 忘れがたい = unforgettable. It is formal and rather literary, and pairs with a limited set of verbs of thinking, feeling, and perception. The whole compound behaves like an い-adjective.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It joins only a narrow set of verbs (信じる, 想像する, 理解する, 忘れる, 認める); it does not combine freely with any verb the way にくい does.
More formal and written than 〜にくい; in casual speech people usually say にくい or づらい instead.
Attach it to the stem: 信じがたい, not 信じるがたい.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It joins only a narrow set of verbs (信じる, 想像する, 理解する, 忘れる, 認める); it does not combine freely with any verb the way にくい does.
More formal and written than 〜にくい; in casual speech people usually say にくい or づらい instead.
Attach it to the stem: 信じがたい, not 信じるがたい.');
SET @Parents += @@ROWCOUNT;
