IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ka-to-iu-to-reason', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'かというと' AND DATALENGTH(c.Pattern) = DATALENGTH(N'かというと') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'かというと' AND DATALENGTH(c.Reading) = DATALENGTH(N'かというと') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Nếu hỏi tại sao thì', Formation = N'なぜ／どうして ＋ mệnh đề ＋ かというと、lý do ＋ からだ', Explanation = N'Nhắc lại câu hỏi về nguyên nhân rồi dẫn vào lời giải thích.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'as for why…; the reason is…' AND DATALENGTH(c.Meaning) = DATALENGTH(N'as for why…; the reason is…') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'なぜ ＋ Sentence［plain form］＋ かというと ＋ …からだ' AND DATALENGTH(c.Formation) = DATALENGTH(N'なぜ ＋ Sentence［plain form］＋ かというと ＋ …からだ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'なぜ〜かというと sets up a question — typically ''why?'' — and then answers it, a smooth way to introduce an explanation. It usually closes with からだ／のだ. Think of it as ''if you ask why…, it''s because…''.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'なぜ〜かというと sets up a question — typically ''why?'' — and then answers it, a smooth way to introduce an explanation. It usually closes with からだ／のだ. Think of it as ''if you ask why…, it''s because…''.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It typically opens with a question word (なぜ, どうして) and closes with からだ／ためだ; dropping that closing reason feels unfinished.
Keep this ''explaining a reason'' use apart from かというと meaning ''if I had to choose'' — the reason use hinges on a why-question.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It typically opens with a question word (なぜ, どうして) and closes with からだ／ためだ; dropping that closing reason feels unfinished.
Keep this ''explaining a reason'' use apart from かというと meaning ''if I had to choose'' — the reason use hinges on a why-question.');
