WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'kara-iu-to' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'kara-iu-to');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: kara-iu-to', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'から言うと' AND DATALENGTH(c.Pattern) = DATALENGTH(N'から言うと') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'からいうと' AND DATALENGTH(c.Reading) = DATALENGTH(N'からいうと') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Xét theo, nói từ góc độ', Formation = N'Danh từ chỉ căn cứ hoặc tiêu chí ＋ から言うと', Explanation = N'Nêu căn cứ hoặc góc nhìn dùng để đưa ra nhận định.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'from the standpoint of; judging from; in terms of' AND DATALENGTH(c.Meaning) = DATALENGTH(N'from the standpoint of; judging from; in terms of') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ から言うと／から言えば' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ から言うと／から言えば') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜から言うと presents a judgment made from a particular standpoint or basis — 私の経験から言うと = speaking from my experience. It names the angle you are judging from, then gives the conclusion that follows.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜から言うと presents a judgment made from a particular standpoint or basis — 私の経験から言うと = speaking from my experience. It names the angle you are judging from, then gives the conclusion that follows.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It follows a noun naming a viewpoint or basis (経験, 立場, 結果); it doesn''t attach to plain verbs directly.
Close to からすると／からすれば; から言うと foregrounds ''putting it into words from this angle''.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It follows a noun naming a viewpoint or basis (経験, 立場, 結果); it doesn''t attach to plain verbs directly.
Close to からすると／からすれば; から言うと foregrounds ''putting it into words from this angle''.');
SET @Parents += @@ROWCOUNT;
