AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'kara-iu-to:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'kara-iu-to:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'私の経験から言うと、この方法はうまくいかない。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'私の経験から言うと、この方法はうまくいかない。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
