AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'kara-iu-to:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'kara-iu-to:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'値段から言うと、この店はけっして安くない。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'値段から言うと、この店はけっして安くない。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N3-G-007.json: kara-koso
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'kara-koso' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'kara-koso');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: kara-koso', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'からこそ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'からこそ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'からこそ' AND DATALENGTH(c.Reading) = DATALENGTH(N'からこそ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Chính vì… nên', Formation = N'Mệnh đề thể thường ＋ からこそ', Explanation = N'Nhấn mạnh rằng lý do được nêu là yếu tố quyết định.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'precisely because; it is exactly because ~ that ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'precisely because; it is exactly because ~ that ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence［plain form］＋ からこそ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence［plain form］＋ からこそ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜からこそ emphasizes that this reason, and no other, is the real cause — 家族がいるからこそがんばれる = it''s precisely because I have a family that I can keep going. こそ highlights the から clause as the one decisive reason, often for something positive.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜からこそ emphasizes that this reason, and no other, is the real cause — 家族がいるからこそがんばれる = it''s precisely because I have a family that I can keep going. こそ highlights the から clause as the one decisive reason, often for something positive.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It stresses one reason as the true, decisive one; plain から just states a reason without that emphasis.
The main clause often takes のだ／んです to complete the ''that''s exactly why…'' feel.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It stresses one reason as the true, decisive one; plain から just states a reason without that emphasis.
The main clause often takes のだ／んです to complete the ''that''s exactly why…'' feel.');
SET @Parents += @@ROWCOUNT;
