BEGIN
UPDATE c SET Meaning = N'Hơi, có dấu hiệu', Formation = N'Gốc ます hoặc danh từ ＋ 気味（ぎみ）', Explanation = N'Chỉ dấu hiệu nhẹ hoặc một xu hướng mới xuất hiện, thường là điều khiến người nói lưu ý.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'a touch of; a bit; tending toward (a slight sign of)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'a touch of; a bit; tending toward (a slight sign of)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun／Verb［stem］＋ 気味' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun／Verb［stem］＋ 気味') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜気味 attaches to a noun or verb stem to say there is a slight touch or trace of something — 風邪気味 = a touch of a cold, 疲れ気味 = a bit tired. It marks a mild sign or leaning, usually of something not great.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜気味 attaches to a noun or verb stem to say there is a slight touch or trace of something — 風邪気味 = a touch of a cold, 疲れ気味 = a bit tired. It marks a mild sign or leaning, usually of something not great.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It marks a slight degree (''a bit, a touch''), not a full-blown state; 風邪気味 is coming down with a cold, not having a bad one.
