BEGIN
UPDATE c SET Meaning = N'Làm hết, làm đến cùng', Formation = N'Gốc ます ＋ 切る', Explanation = N'Nhấn mạnh hành động được thực hiện trọn vẹn hoặc đến giới hạn.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to do completely, all the way to the end (or to the limit)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to do completely, all the way to the end (or to the limit)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ 切る' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ 切る') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜切る attaches to the ます-stem to say you do an action completely, all the way to the end or the limit — 使い切る = use up entirely, 読み切る = read through to the finish. It can also stress reaching an extreme (疲れ切る = be utterly exhausted).' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜切る attaches to the ます-stem to say you do an action completely, all the way to the end or the limit — 使い切る = use up entirely, 読み切る = read through to the finish. It can also stress reaching an extreme (疲れ切る = be utterly exhausted).') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Attach it to the stem: 食べ切る, not 食べる切る.
