UPDATE c SET Meaning = N'Vậy mà, dù… vẫn (trách móc)', Formation = N'Mệnh đề bổ nghĩa ＋ くせに', Explanation = N'Nêu điều trái với kỳ vọng kèm thái độ chê trách hoặc coi thường.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'even though; despite (with blame or contempt)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'even though; despite (with blame or contempt)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb／い-adjective［plain form］＋ くせに
