WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'koto-da' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'koto-da');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: koto-da', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ことだ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ことだ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ことだ' AND DATALENGTH(c.Reading) = DATALENGTH(N'ことだ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Nên làm, điều cần làm là', Formation = N'Động từ thể từ điển hoặc thể ない ＋ ことだ', Explanation = N'Khuyên trực tiếp nên làm hoặc tránh một việc.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'should; the thing to do is to ~ (direct advice)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'should; the thing to do is to ~ (direct advice)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］／［ない form］＋ ことだ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］／［ない form］＋ ことだ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Attached to a verb, ことだ delivers direct advice or a recommendation — ''the best thing is to do X.'' It sounds firm and a little instructive, as if handing down the sensible course of action. Use the dictionary form for what to do, the ない-form for what to avoid.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Attached to a verb, ことだ delivers direct advice or a recommendation — ''the best thing is to do X.'' It sounds firm and a little instructive, as if handing down the sensible course of action. Use the dictionary form for what to do, the ない-form for what to avoid.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'This advice sense attaches to a verb; when ことだ follows a feeling word (うれしいことだ) it is instead an exclamation, a different use.
It can sound top-down, like giving a lesson; for gentler suggestions use ほうがいい or 〜といい.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'This advice sense attaches to a verb; when ことだ follows a feeling word (うれしいことだ) it is instead an exclamation, a different use.
It can sound top-down, like giving a lesson; for gentler suggestions use ほうがいい or 〜といい.');
SET @Parents += @@ROWCOUNT;
