AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'koto-da:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'koto-da:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'上手になりたいなら、毎日練習することだ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'上手になりたいなら、毎日練習することだ。')
