AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'koto-da:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'koto-da:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'風邪のときは、無理をせずにゆっくり休むことだ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'風邪のときは、無理をせずにゆっくり休むことだ。')
