WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'koto-nano' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'koto-nano');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: koto-nano', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ことなの' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ことなの') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ことなの' AND DATALENGTH(c.Reading) = DATALENGTH(N'ことなの') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Điều đó có nghĩa là', Formation = N'Mệnh đề ＋ ことなのだ／ことなのです', Explanation = N'こと danh từ hóa hành động, còn なのだ trình bày nó như lời giải thích.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'it means (doing) ~; it comes down to ~; what it is, is ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'it means (doing) ~; it comes down to ~; what it is, is ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun／〜というのは ＋ Verb［plain form］＋ ことなのだ／ことなの' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun／〜というのは ＋ Verb［plain form］＋ ことなのだ／ことなの') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ことなのだ (casual ことなの, polite ことなのです) restates a topic as what it fundamentally amounts to. It takes a plain clause, packages it as a こと — a matter or act — and equates the topic with it, explaining ''what X really is / what it means.'' The な comes from こと being treated with the explanatory の.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ことなのだ (casual ことなの, polite ことなのです) restates a topic as what it fundamentally amounts to. It takes a plain clause, packages it as a こと — a matter or act — and equates the topic with it, explaining ''what X really is / what it means.'' The な comes from こと being treated with the explanatory の.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The な is required because こと takes the explanatory の: ことなのだ, not ことのだ.
This is a defining ''it means that ~,'' distinct from the advice ことだ that attaches to a verb (''you should ~'').' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The な is required because こと takes the explanatory の: ことなのだ, not ことのだ.
This is a defining ''it means that ~,'' distinct from the advice ことだ that attaches to a verb (''you should ~'').');
SET @Parents += @@ROWCOUNT;
