IF @Matches > 1 THROW 51001, 'Ambiguous translation source: koto-ni', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ことに' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ことに') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ことに' AND DATALENGTH(c.Reading) = DATALENGTH(N'ことに') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Điều đáng… là', Formation = N'Động từ thể た hoặc tính từ bổ nghĩa ＋ ことに', Explanation = N'Đưa cảm xúc hay nhận xét của người nói lên trước sự việc.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to my ~ (surprise, delight, regret); ~ enough' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to my ~ (surprise, delight, regret); ~ enough') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［た form］／い-adjective／な-adjective［な］＋ ことに、＋ Sentence' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［た form］／い-adjective／な-adjective［な］＋ ことに、＋ Sentence') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ことに puts a feeling word up front to color the fact that follows — 驚いたことに (to my surprise), 残念なことに (regrettably). The emotion is the speaker''s reaction to what comes next, delivered as a lead-in before the main clause.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ことに puts a feeling word up front to color the fact that follows — 驚いたことに (to my surprise), 残念なことに (regrettably). The emotion is the speaker''s reaction to what comes next, delivered as a lead-in before the main clause.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Only emotion words fit (驚いた, うれしい, 残念な); a neutral verb like 食べた does not work here.
The feeling comes first as a reaction; the fact that caused it follows after ことに.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Only emotion words fit (驚いた, うれしい, 残念な); a neutral verb like 食べた does not work here.
The feeling comes first as a reaction; the fact that caused it follows after ことに.');
