BEGIN
UPDATE c SET Meaning = N'Theo quy định, theo lịch sẽ', Formation = N'Động từ thể từ điển hoặc thể ない ＋ ことになっている', Explanation = N'Nêu quy định hoặc sự sắp xếp đang có hiệu lực.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'it is a rule / arrangement / custom that ~; is supposed to ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'it is a rule / arrangement / custom that ~; is supposed to ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］／［ない form］＋ ことになっている' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］／［ない form］＋ ことになっている') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ことになっている describes a rule, arrangement, or custom that is already in place and expected to hold — a school regulation, a schedule, a standing plan. It presents the situation as an established norm rather than a fresh decision.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ことになっている describes a rule, arrangement, or custom that is already in place and expected to hold — a school regulation, a schedule, a standing plan. It presents the situation as an established norm rather than a fresh decision.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'ことになっている is a standing rule or arrangement in place; ことになる is a decision or outcome coming about at some point.
