WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'sugata' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'sugata');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: sugata', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'〜(の)姿' AND DATALENGTH(c.Pattern) = DATALENGTH(N'〜(の)姿') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'すがた' AND DATALENGTH(c.Reading) = DATALENGTH(N'すがた') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Dáng vẻ, hình ảnh khi làm hoặc mặc gì', Formation = N'Danh từ ＋ の姿／mệnh đề bổ nghĩa ＋ 姿／tên trang phục ＋ 姿', Explanation = N'Nêu hình ảnh có thể nhìn thấy của một người hoặc nhóm người.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'figure; the visible sight of someone (doing something)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'figure; the visible sight of someone (doing something)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［plain form］＋ 姿
Noun ＋ の ＋ 姿' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［plain form］＋ 姿
Noun ＋ の ＋ 姿') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'姿 is a noun for a person''s figure or appearance — the way they look, often caught in a particular moment. 〜(の)姿 lets you point to "the sight of someone doing ~": 走る姿 = the sight of them running, 着物姿 = a figure in a kimono. It highlights the visible form of a person.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'姿 is a noun for a person''s figure or appearance — the way they look, often caught in a particular moment. 〜(の)姿 lets you point to "the sight of someone doing ~": 走る姿 = the sight of them running, 着物姿 = a figure in a kimono. It highlights the visible form of a person.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'姿 is about a person''s visible figure or form; for the general look or state of things in the abstract, 様子 or 見た目 usually fit better.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'姿 is about a person''s visible figure or form; for the general look or state of things in the abstract, 様子 or 見た目 usually fit better.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Tôi thấy vui khi nhìn lũ trẻ chơi đùa đầy sức sống.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'sugata:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'sugata:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'子どもたちが元気に遊ぶ姿を見ると、うれしくなる。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'子どもたちが元気に遊ぶ姿を見ると、うれしくなる。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Cô ấy mặc kimono trông rất đẹp.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'sugata:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'sugata:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼女の着物姿はとてもきれいだった。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼女の着物姿はとてもきれいだった。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
