SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'zutsu' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'zutsu');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: zutsu', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ずつ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ずつ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ずつ' AND DATALENGTH(c.Reading) = DATALENGTH(N'ずつ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Mỗi, từng, mỗi lần một ít', Formation = N'Số lượng hoặc 少し ＋ ずつ', Explanation = N'Chỉ phần phân đều hoặc lượng tăng thêm qua từng lần.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'each; apiece; at a time; in steady increments' AND DATALENGTH(c.Meaning) = DATALENGTH(N'each; apiece; at a time; in steady increments') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Number／quantity ＋ ずつ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Number／quantity ＋ ずつ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ずつ follows a quantity to mean "that much each" or "that much at a time" — 一つずつ = one apiece, 少しずつ = little by little, 三個ずつ = three each. It spreads an amount evenly across people or occasions, or marks steady, equal increments.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ずつ follows a quantity to mean "that much each" or "that much at a time" — 一つずつ = one apiece, 少しずつ = little by little, 三個ずつ = three each. It spreads an amount evenly across people or occasions, or marks steady, equal increments.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'ずつ needs a quantity word in front of it (一つ, 少し, 千円); it doesn''t attach straight onto a plain noun.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'ずつ needs a quantity word in front of it (一つ, 少し, 千円); it doesn''t attach straight onto a plain noun.');
SET @Parents += @@ROWCOUNT;
