AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'zutsu:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'zutsu:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'子どもたちにお菓子を二つずつ配った。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'子どもたちにお菓子を二つずつ配った。')
