WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'zutto-comparison' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'zutto-comparison');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: zutto-comparison', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ずっと' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ずっと') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ずっと' AND DATALENGTH(c.Reading) = DATALENGTH(N'ずっと') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Hơn hẳn, hơn nhiều', Formation = N'Mốc so sánh ＋ より ＋ ずっと ＋ đặc điểm', Explanation = N'Nhấn mạnh khoảng cách lớn giữa hai đối tượng được so sánh.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'by far; way (more); far and away — in comparisons' AND DATALENGTH(c.Meaning) = DATALENGTH(N'by far; way (more); far and away — in comparisons') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'... より ＋ ずっと ＋ adjective／adverb
ずっと ＋ adjective／adverb（by far）' AND DATALENGTH(c.Formation) = DATALENGTH(N'... より ＋ ずっと ＋ adjective／adverb
ずっと ＋ adjective／adverb（by far）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'In a comparison, ずっと intensifies the gap — "by far," "way more," "far and away." AよりずっとB stresses that B beats A by a wide margin, not just barely. Note this is a separate sense from the ずっと that means "the whole time / continuously."' AND DATALENGTH(c.Explanation) = DATALENGTH(N'In a comparison, ずっと intensifies the gap — "by far," "way more," "far and away." AよりずっとB stresses that B beats A by a wide margin, not just barely. Note this is a separate sense from the ずっと that means "the whole time / continuously."') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'This comparative ずっと emphasizes a big difference; the same word also means "continuously / the whole time," so let the context tell them apart.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'This comparative ずっと emphasizes a big difference; the same word also means "continuously / the whole time," so let the context tell them apart.');
SET @Parents += @@ROWCOUNT;
