IF @Matches > 1 THROW 51001, 'Ambiguous translation source: sude-ni', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'すでに' AND DATALENGTH(c.Pattern) = DATALENGTH(N'すでに') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'すでに' AND DATALENGTH(c.Reading) = DATALENGTH(N'すでに') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Đã, từ trước rồi', Formation = N'すでに ＋ vị ngữ', Explanation = N'Nêu việc đã hoàn thành hoặc trạng thái đã có ở mốc đang nói đến.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'already; previously (something is already done or the case)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'already; previously (something is already done or the case)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'すでに ＋ Verb（already done / already the case）' AND DATALENGTH(c.Formation) = DATALENGTH(N'すでに ＋ Verb（already done / already the case）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'すでに says an action or state is "already" done or in place by a given point — 会議はすでに始まっていた = the meeting had already started. It''s the more formal, written cousin of もう, and unlike もう it isn''t used for "soon" or "not anymore."' AND DATALENGTH(c.Explanation) = DATALENGTH(N'すでに says an action or state is "already" done or in place by a given point — 会議はすでに始まっていた = the meeting had already started. It''s the more formal, written cousin of もう, and unlike もう it isn''t used for "soon" or "not anymore."') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'すでに is fairly formal and written; in everyday speech もう is the natural choice.
Unlike もう, すでに only means "already" — it isn''t used for "(not) any longer" or "soon."' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'すでに is fairly formal and written; in everyday speech もう is the natural choice.
Unlike もう, すでに only means "already" — it isn''t used for "(not) any longer" or "soon."');
