FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'namely; that is to say; in other words' AND DATALENGTH(c.Meaning) = DATALENGTH(N'namely; that is to say; in other words') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence／Noun ＋ すなわち ＋ restatement' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence／Noun ＋ すなわち ＋ restatement') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'すなわち restates what came just before, more precisely — "namely," "that is," "in other words." It equates two things, where the second is a clearer or more exact version of the first. It''s formal and common in writing, explanations, and definitions.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'すなわち restates what came just before, more precisely — "namely," "that is," "in other words." It equates two things, where the second is a clearer or more exact version of the first. It''s formal and common in writing, explanations, and definitions.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'すなわち is formal and equates terms precisely; for a casual "in other words / basically," use つまり.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'すなわち is formal and equates terms precisely; for a casual "in other words / basically," use つまり.');
