FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'because of; due to (blaming an unwanted result on a cause)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'because of; due to (blaming an unwanted result on a cause)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ の ＋ せいで
