IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'前者は・後者は' AND DATALENGTH(c.Pattern) = DATALENGTH(N'前者は・後者は') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ぜんしゃは・こうしゃは' AND DATALENGTH(c.Reading) = DATALENGTH(N'ぜんしゃは・こうしゃは') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Đối tượng trước, đối tượng sau', Formation = N'Nêu A và B, rồi dùng 前者／後者 ＋ は／のほうが', Explanation = N'前者 thay cho A, còn 後者 thay cho B theo thứ tự đã nêu.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'the former ~ ; the latter ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'the former ~ ; the latter ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'… 前者は … 、後者は … ' AND DATALENGTH(c.Formation) = DATALENGTH(N'… 前者は … 、後者は … ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'前者 means "the former" (the first of two things mentioned) and 後者 means "the latter" (the second). Used together, they let you refer back to two items without repeating them: 前者は安く、後者は速い = the former is cheap, the latter is fast. It''s a formal pairing, common in writing and comparisons.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'前者 means "the former" (the first of two things mentioned) and 後者 means "the latter" (the second). Used together, they let you refer back to two items without repeating them: 前者は安く、後者は速い = the former is cheap, the latter is fast. It''s a formal pairing, common in writing and comparisons.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'前者／後者 work only when exactly two things have been named; for three or more, refer to them by name instead.
後者 is read こうしゃ; don''t read this pair as the time words 前 (before) / 後 (after).' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'前者／後者 work only when exactly two things have been named; for three or more, refer to them by name instead.
後者 is read こうしゃ; don''t read this pair as the time words 前 (before) / 後 (after).');
