WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'tsui' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'tsui');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: tsui', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'つい' AND DATALENGTH(c.Pattern) = DATALENGTH(N'つい') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'つい' AND DATALENGTH(c.Reading) = DATALENGTH(N'つい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Lỡ, vô tình, bất giác', Formation = N'つい ＋ động từ (thường đi với てしまう)', Explanation = N'Nói về việc làm ngoài dự định hoặc không cưỡng lại được.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'without meaning to; end up doing despite oneself' AND DATALENGTH(c.Meaning) = DATALENGTH(N'without meaning to; end up doing despite oneself') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'つい ＋ Verb ＋ （てしまう）' AND DATALENGTH(c.Formation) = DATALENGTH(N'つい ＋ Verb ＋ （てしまう）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'つい marks doing something you didn''t really mean to do — you slip and do it despite knowing better, often out of habit or weak willpower. It very frequently pairs with 〜てしまう, which underlines the unintended result. Typical of everyday confessions like eating sweets or staying up too late.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'つい marks doing something you didn''t really mean to do — you slip and do it despite knowing better, often out of habit or weak willpower. It very frequently pairs with 〜てしまう, which underlines the unintended result. Typical of everyday confessions like eating sweets or staying up too late.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'つい is about slipping into an unintended action; don''t confuse it with ついに (finally, at last).
It commonly teams up with 〜てしまう to stress that the result was unintended: つい食べてしまった.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'つい is about slipping into an unintended action; don''t confuse it with ついに (finally, at last).
It commonly teams up with 〜てしまう to stress that the result was unintended: つい食べてしまった.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Đang ăn kiêng mà tôi lỡ ăn đồ ngọt.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'tsui:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'tsui:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'ダイエット中なのに、つい甘いものを食べてしまった。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'ダイエット中なのに、つい甘いものを食べてしまった。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Sách hay quá nên tôi đọc mãi đến khuya.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'tsui:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'tsui:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'面白くて、つい夜遅くまで本を読んでしまった。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'面白くて、つい夜遅くまで本を読んでしまった。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
