AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'tsuide-ni' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'tsuide-ni');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: tsuide-ni', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ついでに' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ついでに') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ついでに' AND DATALENGTH(c.Reading) = DATALENGTH(N'ついでに') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Nhân tiện, tiện thể', Formation = N'Động từ thể từ điển hoặc thể た ＋ ついでに／danh từ ＋ のついでに', Explanation = N'Tận dụng dịp thực hiện việc chính để làm thêm việc khác.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'while you''re at it; on the same occasion; on the way' AND DATALENGTH(c.Meaning) = DATALENGTH(N'while you''re at it; on the same occasion; on the way') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］／［た form］＋ ついでに
Noun ＋ の ＋ ついでに' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］／［た form］＋ ついでに
Noun ＋ の ＋ ついでに') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ついでに marks doing a second thing while you''re already doing the first — you take advantage of one occasion to get another errand done at little extra effort. It attaches to a verb (dictionary or た form) or to a noun with の. The main action comes first; the ついでに action is the bonus.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ついでに marks doing a second thing while you''re already doing the first — you take advantage of one occasion to get another errand done at little extra effort. It attaches to a verb (dictionary or た form) or to a noun with の. The main action comes first; the ついでに action is the bonus.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The primary action is stated first; the ついでに part is the extra, secondary thing done ''while you''re at it.''
Attach it to a noun with の: 散歩のついでに, not 散歩ついでに.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The primary action is stated first; the ついでに part is the extra, secondary thing done ''while you''re at it.''
Attach it to a noun with の: 散歩のついでに, not 散歩ついでに.');
