AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'ppanashi:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'ppanashi:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'窓を開けっぱなしにしていたら、部屋が寒くなった。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'窓を開けっぱなしにしていたら、部屋が寒くなった。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
