-- N3-G-022.json: ppoi
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'ppoi' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'ppoi');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ppoi', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'っぽい' AND DATALENGTH(c.Pattern) = DATALENGTH(N'っぽい') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'っぽい' AND DATALENGTH(c.Reading) = DATALENGTH(N'っぽい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Có vẻ như, mang tính, hay', Formation = N'Danh từ hoặc gốc ます ＋ っぽい', Explanation = N'Gợi đặc điểm nổi bật hoặc khuynh hướng. Từ tạo thành chia như tính từ い.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'-ish; -like; has the quality of; tends to' AND DATALENGTH(c.Meaning) = DATALENGTH(N'-ish; -like; has the quality of; tends to') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ っぽい
い-adjective［stem］／Verb［stem］＋ っぽい' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ っぽい
い-adjective［stem］／Verb［stem］＋ っぽい') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'っぽい tacks onto a noun, adjective stem, or verb stem to say something has the quality or tendency of that word — 子供っぽい = childish, 忘れっぽい = forgetful, 安っぽい = cheap-looking. The whole compound behaves like an い-adjective. It''s colloquial and often carries a mildly critical tone.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'っぽい tacks onto a noun, adjective stem, or verb stem to say something has the quality or tendency of that word — 子供っぽい = childish, 忘れっぽい = forgetful, 安っぽい = cheap-looking. The whole compound behaves like an い-adjective. It''s colloquial and often carries a mildly critical tone.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'With a verb stem it means ''tends to / easily does'' (怒りっぽい = quick to anger), not ''looks like.''
It''s casual and can sound negative: 安っぽい means ''cheap-looking,'' not simply ''inexpensive.''' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'With a verb stem it means ''tends to / easily does'' (怒りっぽい = quick to anger), not ''looks like.''
It''s casual and can sound negative: 安っぽい means ''cheap-looking,'' not simply ''inexpensive.''');
SET @Parents += @@ROWCOUNT;
