BEGIN
UPDATE c SET Meaning = N'Tức là, tóm lại', Formation = N'Ý trước ＋ つまり ＋ ý diễn giải hoặc kết luận', Explanation = N'Nói lại cho rõ hoặc rút ra kết luận từ thông tin vừa nêu.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'in other words; that is to say; in short' AND DATALENGTH(c.Meaning) = DATALENGTH(N'in other words; that is to say; in short') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence。＋ つまり ＋ Sentence（restatement）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence。＋ つまり ＋ Sentence（restatement）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'つまり introduces a restatement or summary of what was just said — you rephrase it more simply or boil it down to its point. ''In other words / that is to say / in short.'' It links a fuller explanation to a tighter conclusion drawn from it.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'つまり introduces a restatement or summary of what was just said — you rephrase it more simply or boil it down to its point. ''In other words / that is to say / in short.'' It links a fuller explanation to a tighter conclusion drawn from it.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'つまり restates or sums up the same content; it doesn''t introduce a new result the way だから or それで does.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'つまり restates or sums up the same content; it doesn''t introduce a new result the way だから or それで does.');
