FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'had intended to (but didn''t); thought I had done' AND DATALENGTH(c.Meaning) = DATALENGTH(N'had intended to (but didn''t); thought I had done') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ つもりだった
