AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'dewa-nakute' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'dewa-nakute');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: dewa-nakute', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ではなくて・じゃなくて' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ではなくて・じゃなくて') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ではなくて・じゃなくて' AND DATALENGTH(c.Reading) = DATALENGTH(N'ではなくて・じゃなくて') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Không phải A mà là B', Formation = N'A ＋ ではなくて／じゃなくて、B', Explanation = N'Sửa hoặc thay cách xác định A bằng B. じゃなくて là dạng thân mật.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'not A but B; it isn''t A, (it''s B)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'not A but B; it isn''t A, (it''s B)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun／な-adjective ＋ ではなくて／じゃなくて ＋ B' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun／な-adjective ＋ ではなくて／じゃなくて ＋ B') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜ではなくて (casual じゃなくて) negates one noun and connects on to the correct one — これは私のではなくて、姉のです = this isn''t mine, it''s my sister''s. It is the connective (て) form of ではない, used to swap out a wrong choice for the right one.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜ではなくて (casual じゃなくて) negates one noun and connects on to the correct one — これは私のではなくて、姉のです = this isn''t mine, it''s my sister''s. It is the connective (て) form of ではない, used to swap out a wrong choice for the right one.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'で is copula-based, so this frame is for nouns and な-adjectives; for verbs and い-adjectives use the plain negative + くて (安くなくて) or 〜のではなくて.
じゃなくて is just the casual contraction of ではなくて — same meaning, softer register.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'で is copula-based, so this frame is for nouns and な-adjectives; for verbs and い-adjectives use the plain negative + くて (安くなくて) or 〜のではなくて.
じゃなくて is just the casual contraction of ではなくて — same meaning, softer register.');
