BEGIN
UPDATE c SET Meaning = N'Dù có hay không', Formation = N'Động từ thể て ＋ も ＋ cùng động từ dạng なくても', Explanation = N'Nêu hai khả năng đối lập cùng dẫn đến một kết quả.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'whether ~ or not (the result is the same)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'whether ~ or not (the result is the same)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ も ＋ Verb［ない form → なくて］＋ も
