SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'temo-kamawanai' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'temo-kamawanai');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: temo-kamawanai', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ても構わない' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ても構わない') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'てもかまわない' AND DATALENGTH(c.Reading) = DATALENGTH(N'てもかまわない') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Dù… cũng được, có phiền không?', Formation = N'Động từ thể て ＋ も構わない／tính từ dạng くても／danh từ ＋ でも構わない', Explanation = N'Cho biết điều kiện đó vẫn chấp nhận được. Dạng câu hỏi dùng để xin phép.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'it''s fine even if ~; I don''t mind if ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'it''s fine even if ~; I don''t mind if ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ もかまわない
い-adjective：〜くてもかまわない
Noun／な-adjective：〜でもかまわない' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］＋ もかまわない
い-adjective：〜くてもかまわない
Noun／な-adjective：〜でもかまわない') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜てもかまわない says that even if X happens, it doesn''t bother the speaker — so it grants permission or shows willingness. 高くてもかまわない = I don''t mind if it''s expensive. 構わない literally means ''don''t mind'', giving it a softer feel than the blunter てもいい.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜てもかまわない says that even if X happens, it doesn''t bother the speaker — so it grants permission or shows willingness. 高くてもかまわない = I don''t mind if it''s expensive. 構わない literally means ''don''t mind'', giving it a softer feel than the blunter てもいい.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'構わない means ''don''t mind'', so it reads as gentle permission; てもいい is a more direct ''may / it''s okay to''.
The negative なくてもかまわない means ''it''s fine even if you don''t''.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'構わない means ''don''t mind'', so it reads as gentle permission; てもいい is a more direct ''may / it''s okay to''.
The negative なくてもかまわない means ''it''s fine even if you don''t''.');
SET @Parents += @@ROWCOUNT;
