AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'temo-kamawanai:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'temo-kamawanai:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'ここで写真を撮ってもかまいませんか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'ここで写真を撮ってもかまいませんか。')
