END ELSE SET @Skipped += 1;
-- N3-G-028.json: to-iu-yori
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'to-iu-yori' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'to-iu-yori');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: to-iu-yori', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'というより' AND DATALENGTH(c.Pattern) = DATALENGTH(N'というより') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'というより' AND DATALENGTH(c.Reading) = DATALENGTH(N'というより') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Nói đúng hơn là', Formation = N'A ＋ というより（も）、B', Explanation = N'Đưa ra nhận định B vì sát hơn cách gọi hoặc nhận xét A.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'rather than ~; more like B than A' AND DATALENGTH(c.Meaning) = DATALENGTH(N'rather than ~; more like B than A') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun／な-adjective／Sentence ＋ というより' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun／な-adjective／Sentence ＋ というより') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜というより refines how you describe one thing, saying B is a more accurate label than A — 優しいというより気が弱い = not so much kind as timid. It compares two descriptions of the same thing and is often followed by むしろ (''rather'').' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜というより refines how you describe one thing, saying B is a more accurate label than A — 優しいというより気が弱い = not so much kind as timid. It compares two descriptions of the same thing and is often followed by むしろ (''rather'').') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It weighs two descriptions of one thing, not two separate options — that latter job belongs to plain より.
It''s often reinforced by むしろ in the second half.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It weighs two descriptions of one thing, not two separate options — that latter job belongs to plain より.
It''s often reinforced by むしろ in the second half.');
SET @Parents += @@ROWCOUNT;
