AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'to-iu-yori:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'to-iu-yori:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼は優しいというより、ただ気が弱いだけだ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼は優しいというより、ただ気が弱いだけだ。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Gọi đây là công việc thì đúng hơn là sở thích.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'to-iu-yori:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'to-iu-yori:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'これは趣味というより、もう仕事だね。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'これは趣味というより、もう仕事だね。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
