AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'to-iu-riyuu-de' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'to-iu-riyuu-de');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: to-iu-riyuu-de', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'という理由で' AND DATALENGTH(c.Pattern) = DATALENGTH(N'という理由で') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'というりゆうで' AND DATALENGTH(c.Reading) = DATALENGTH(N'というりゆうで') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Vì lý do, với lý do', Formation = N'Mệnh đề thể thường ＋ という理由で', Explanation = N'Nêu lý do được đưa ra cho quyết định hoặc sự việc.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'for the reason that ~; on the grounds that ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'for the reason that ~; on the grounds that ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence［plain form］／Noun ＋ という理由で' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence［plain form］／Noun ＋ という理由で') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜という理由で presents the stated matter as the given or official reason for something — 体調が悪いという理由で欠席した = missed it on the grounds of feeling unwell. It''s more explicit and formal than plain から, and can hint that the reason is merely the stated pretext.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜という理由で presents the stated matter as the given or official reason for something — 体調が悪いという理由で欠席した = missed it on the grounds of feeling unwell. It''s more explicit and formal than plain から, and can hint that the reason is merely the stated pretext.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It''s more formal and explicit than から, naming the reason as ''the grounds''.
Depending on context it can carry a ''under the pretext of ~'' undertone.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It''s more formal and explicit than から, naming the reason as ''the grounds''.
Depending on context it can carry a ''under the pretext of ~'' undertone.');
