BEGIN
UPDATE c SET Meaning = N'Nhắc đến, nói đến', Formation = N'Chủ đề ＋ と言えば', Explanation = N'Lấy một điều vừa được nhắc làm điểm chuyển sang liên tưởng hoặc chuyện liên quan.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'speaking of ~; if you mention ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'speaking of ~; if you mention ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun／Sentence ＋ といえば' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun／Sentence ＋ といえば') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜といえば takes up a word or topic just raised and offers the association or comment it evokes — 夏といえば花火 = speaking of summer, fireworks. It''s the go-to way to say ''now that you mention ~'' and bring up a representative example or a related remark.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜といえば takes up a word or topic just raised and offers the association or comment it evokes — 夏といえば花火 = speaking of summer, fireworks. It''s the go-to way to say ''now that you mention ~'' and bring up a representative example or a related remark.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Very close to というと; といえば slightly emphasizes the speaker''s own strong association or a typical example.
