IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'と言える' AND DATALENGTH(c.Pattern) = DATALENGTH(N'と言える') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'といえる' AND DATALENGTH(c.Reading) = DATALENGTH(N'といえる') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Có thể nói rằng', Formation = N'Mệnh đề thể thường ＋ と言える／とは言えない', Explanation = N'Đánh giá có đủ cơ sở để gọi hoặc kết luận như vậy hay không.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'you can say that ~; it can be said that ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'you can say that ~; it can be said that ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence［plain form］＋ と言える' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence［plain form］＋ と言える') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜と言える presents a conclusion as something reasonably assertible — 成功したと言える = you could say it succeeded. It marks a measured, justified judgment rather than a whim, and is common in analysis. The negative 〜とは言えない means ''you can''t really say that''.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜と言える presents a conclusion as something reasonably assertible — 成功したと言える = you could say it succeeded. It marks a measured, justified judgment rather than a whim, and is common in analysis. The negative 〜とは言えない means ''you can''t really say that''.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It frames a reasoned, defensible conclusion, so it fits essays and analysis, not casual venting.
The negative 〜とは言えない (''you can''t really say that'') is a very common counterpart.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It frames a reasoned, defensible conclusion, so it fits essays and analysis, not casual venting.
The negative 〜とは言えない (''you can''t really say that'') is a very common counterpart.');
