UPDATE c SET Meaning = N'Đúng như, làm theo', Formation = N'Động từ thể thường ＋ とおりに／danh từ ＋ のとおりに／danh từ ＋ どおりに', Explanation = N'Lấy hướng dẫn, dự đoán hoặc mẫu có sẵn làm chuẩn.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'in the same way as; just as; exactly as' AND DATALENGTH(c.Meaning) = DATALENGTH(N'in the same way as; just as; exactly as') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［plain form］＋ とおり（に）
