FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'almost; nearly; was about to (but it didn''t actually happen)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'almost; nearly; was about to (but it didn''t actually happen)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ ところだった
