IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'と同時に' AND DATALENGTH(c.Pattern) = DATALENGTH(N'と同時に') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'とどうじに' AND DATALENGTH(c.Reading) = DATALENGTH(N'とどうじに') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Đồng thời, ngay khi', Formation = N'Mệnh đề thể thường hoặc danh từ ＋ と同時に', Explanation = N'Chỉ hai sự việc xảy ra cùng lúc hoặc hai đặc điểm cùng tồn tại.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'at the same time as; the moment that; while also being' AND DATALENGTH(c.Meaning) = DATALENGTH(N'at the same time as; the moment that; while also being') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ と同時に
Noun ＋ である ＋ と同時に' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ と同時に
Noun ＋ である ＋ と同時に') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'と同時に joins two things that happen or hold at the same time. With events it means ''the instant one happens, so does the other'' — ベルが鳴ると同時に、みんな立ち上がった = the moment the bell rang, everyone stood up. With states it means ''while also being'' — 彼は歌手であると同時に俳優でもある = he is a singer and at the same time an actor. It is fairly formal and common in writing.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'と同時に joins two things that happen or hold at the same time. With events it means ''the instant one happens, so does the other'' — ベルが鳴ると同時に、みんな立ち上がった = the moment the bell rang, everyone stood up. With states it means ''while also being'' — 彼は歌手であると同時に俳優でもある = he is a singer and at the same time an actor. It is fairly formal and common in writing.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It ties two things to the very same moment or holds two qualities at once; it is not a casual ''while'' for background action — for that use ながら.
With a noun, insert である: 教師であると同時に, not 教師と同時に.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It ties two things to the very same moment or holds two qualities at once; it is not a casual ''while'' for background action — for that use ながら.
