UPDATE c SET Meaning = N'Cùng với, song song với', Formation = N'Danh từ hoặc động từ thể từ điển ＋ と共に', Explanation = N'Nêu người cùng tham gia hoặc hai sự thay đổi diễn ra song song.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'together with; along with; at the same time as' AND DATALENGTH(c.Meaning) = DATALENGTH(N'together with; along with; at the same time as') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ と共に
