BEGIN
UPDATE c SET Meaning = N'Không hẳn là không, vẫn có thể', Formation = N'Động từ thể ない ＋ ことはない', Explanation = N'Phủ định hai lần để thừa nhận có khả năng hoặc đôi khi có làm, với sắc thái dè dặt.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
