UPDATE c SET Meaning = N'Tùy theo, do, bằng, bởi', Formation = N'Danh từ ＋ によって／による ＋ danh từ', Explanation = N'Tùy ngữ cảnh, nêu tiêu chí làm thay đổi kết quả, nguyên nhân, phương tiện hoặc tác nhân.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'by means of; due to; by (agent); depending on ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'by means of; due to; by (agent); depending on ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ によって
