AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'no-deshou-ka:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'no-deshou-ka:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'この漢字は、どう読むのでしょうか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'この漢字は、どう読むのでしょうか。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
