AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'no-wa-no-hou-da' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'no-wa-no-hou-da');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: no-wa-no-hou-da', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'のは〜の方だ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'のは〜の方だ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'のは〜のほうだ' AND DATALENGTH(c.Reading) = DATALENGTH(N'のは〜のほうだ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Người hoặc bên… là X', Formation = N'Mệnh đề bổ nghĩa ＋ のは ＋ X ＋ の方だ', Explanation = N'Đưa X vào vị trí được nhấn mạnh, thường khi đối chiếu với một bên khác.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'the one who/that ~ is X (it is X that ~)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'the one who/that ~ is X (it is X that ~)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［plain form］／Sentence ＋ のは ＋ Noun ＋ の方だ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［plain form］／Sentence ＋ のは ＋ Noun ＋ の方だ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'This pattern singles out which side something is really true of, out of two possibilities. のは names the situation, and 〜の方だ points to the party or option it actually applies to — 謝るのはあなたの方だ = the one who should apologize is you. It often corrects or clarifies who or which is really the case, against a mistaken assumption.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'This pattern singles out which side something is really true of, out of two possibilities. のは names the situation, and 〜の方だ points to the party or option it actually applies to — 謝るのはあなたの方だ = the one who should apologize is you. It often corrects or clarifies who or which is really the case, against a mistaken assumption.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'方 here contrasts one side against another; the pattern works when there are two candidates and you are picking which one it truly applies to.
方 in this pattern reads ほう (the ''side/option'' word), not かた (''person/way'').' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'方 here contrasts one side against another; the pattern works when there are two candidates and you are picking which one it truly applies to.
方 in this pattern reads ほう (the ''side/option'' word), not かた (''person/way'').');
SET @Parents += @@ROWCOUNT;
