AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'wa-kurai-desu' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'wa-kurai-desu');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: wa-kurai-desu', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'は〜くらいです' AND DATALENGTH(c.Pattern) = DATALENGTH(N'は〜くらいです') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'は〜くらいです' AND DATALENGTH(c.Reading) = DATALENGTH(N'は〜くらいです') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Cũng chỉ khoảng, cùng lắm chỉ', Formation = N'Chủ đề ＋ は ＋ danh từ hoặc mệnh đề ＋ くらいです', Explanation = N'Nêu giới hạn hoặc việc duy nhất đáng kể trong phạm vi đang nói tới.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'about the only ~ is; roughly the extent of it is ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'about the only ~ is; roughly the extent of it is ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Topic ＋ は ＋ … ＋ くらいです
Verb［plain form］／Noun ＋ くらいです' AND DATALENGTH(c.Formation) = DATALENGTH(N'Topic ＋ は ＋ … ＋ くらいです
Verb［plain form］／Noun ＋ くらいです') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'は〜くらいです presents something as the modest limit of what applies — the most you can say, or the only real example. 運動と言えば、犬の散歩くらいです = as for exercise, dog-walking is about the only one. くらい here downplays the amount or degree, framing it as small or the sole case.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'は〜くらいです presents something as the modest limit of what applies — the most you can say, or the only real example. 運動と言えば、犬の散歩くらいです = as for exercise, dog-walking is about the only one. くらい here downplays the amount or degree, framing it as small or the sole case.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'くらい (also ぐらい) here marks a modest limit or the sole example, not an approximate number like ''10 people or so''.
The tone is downplaying — ''it''s only about this much''; it does not emphasize a large amount.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'くらい (also ぐらい) here marks a modest limit or the sole example, not an approximate number like ''10 people or so''.
The tone is downplaying — ''it''s only about this much''; it does not emphasize a large amount.');
SET @Parents += @@ROWCOUNT;
