IF @Matches > 1 THROW 51001, 'Ambiguous translation source: wa-de-yuumei', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'は〜で有名' AND DATALENGTH(c.Pattern) = DATALENGTH(N'は〜で有名') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'は〜でゆうめい' AND DATALENGTH(c.Reading) = DATALENGTH(N'は〜でゆうめい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Nổi tiếng về, nổi tiếng vì', Formation = N'Chủ thể ＋ は ＋ danh từ ＋ で有名だ／chủ thể ＋ は ＋ mệnh đề ＋ ことで有名だ', Explanation = N'Nêu đặc sản, đặc điểm hoặc lý do khiến chủ thể được biết đến.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'X is famous for ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'X is famous for ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ は ＋ Noun ＋ で有名（だ）
Verb［plain form］＋ ことで有名（だ）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ は ＋ Noun ＋ で有名（だ）
Verb［plain form］＋ ことで有名（だ）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜は〜で有名です says what something is well known for — その町はお茶で有名です = that town is famous for its tea. The で marks the reason or feature it is famous for. To say ''famous for doing something'', nominalize the verb with こと first: 早く走ることで有名だ.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜は〜で有名です says what something is well known for — その町はお茶で有名です = that town is famous for its tea. The で marks the reason or feature it is famous for. To say ''famous for doing something'', nominalize the verb with こと first: 早く走ることで有名だ.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'With で, the place is famous because of that feature; 〜が有名 instead means that feature itself is the famous thing.
For being famous for an action, turn the verb into a noun with こと: 作ることで有名, not 作るで有名.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'With で, the place is famous because of that feature; 〜が有名 instead means that feature itself is the famous thing.
For being famous for an action, turn the verb into a noun with こと: 作ることで有名, not 作るで有名.');
