FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'suddenly; without thinking; a thought or glance crossing one''s mind unbidden' AND DATALENGTH(c.Meaning) = DATALENGTH(N'suddenly; without thinking; a thought or glance crossing one''s mind unbidden') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'ふと ＋ Verb' AND DATALENGTH(c.Formation) = DATALENGTH(N'ふと ＋ Verb') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ふと is an adverb for something that happens suddenly and without intention — especially a thought, feeling, or glance that crosses your mind on its own. ''It just occurred to me...'', ''I happened to glance up...''. It pairs naturally with verbs of noticing, thinking, and looking.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ふと is an adverb for something that happens suddenly and without intention — especially a thought, feeling, or glance that crosses your mind on its own. ''It just occurred to me...'', ''I happened to glance up...''. It pairs naturally with verbs of noticing, thinking, and looking.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'ふと goes with verbs of thinking or noticing (思う, 見る, 思い出す); it isn''t for a sudden loud physical event — for that use 急に or 突然.
It carries no sense of will: the thought or glance comes unbidden, not by choice.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'ふと goes with verbs of thinking or noticing (思う, 見る, 思い出す); it isn''t for a sudden loud physical event — for that use 急に or 突然.
It carries no sense of will: the thought or glance comes unbidden, not by choice.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Chợt ngẩng nhìn trời, tôi thấy một cầu vồng lớn.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'futo:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'futo:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'ふと空を見上げると、大きな虹が出ていた。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'ふと空を見上げると、大きな虹が出ていた。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Tôi chợt nhớ chuyện xưa và thấy bồi hồi.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'futo:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'futo:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'昔のことをふと思い出して、なつかしくなった。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'昔のことをふと思い出して、なつかしくなった。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N3-G-041.json: buri-ni
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'buri-ni' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'buri-ni');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: buri-ni', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ぶりに' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ぶりに') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ぶりに' AND DATALENGTH(c.Reading) = DATALENGTH(N'ぶりに') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Lần đầu sau một khoảng thời gian', Formation = N'Khoảng thời gian ＋ ぶりに ＋ hành động', Explanation = N'Chỉ một việc xảy ra lại sau khoảng thời gian được nêu.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'for the first time in (a span of time); after an interval of ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'for the first time in (a span of time); after an interval of ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun［length of time］＋ ぶり（に）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun［length of time］＋ ぶり（に）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ぶり attaches to a length of time and says that much time passed before something happened again — 三年ぶりに = for the first time in three years. It highlights the gap since the last time the thing occurred. Often followed by に before a verb.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ぶり attaches to a length of time and says that much time passed before something happened again — 三年ぶりに = for the first time in three years. It highlights the gap since the last time the thing occurred. Often followed by に before a verb.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It needs a span of time (三年ぶり), not a point in time; it measures how long it had been.
ぶり highlights the interval since the last occurrence; 以来 instead marks the starting point from which something has continued.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It needs a span of time (三年ぶり), not a point in time; it measures how long it had been.
ぶり highlights the interval since the last occurrence; 以来 instead marks the starting point from which something has continued.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Sau mười năm, tôi mới gặp lại bạn thời cấp ba.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'buri-ni:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'buri-ni:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'十年ぶりに高校の友達に会った。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'十年ぶりに高校の友達に会った。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Sau hai năm, tôi mới lại đi du lịch nước ngoài.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'buri-ni:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'buri-ni:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'二年ぶりに海外旅行に行った。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'二年ぶりに海外旅行に行った。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
