-- N3-G-042.json: furi-o-suru
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'furi-o-suru' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'furi-o-suru');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: furi-o-suru', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ふりをする' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ふりをする') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ふりをする' AND DATALENGTH(c.Reading) = DATALENGTH(N'ふりをする') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Giả vờ làm, làm như thể', Formation = N'Mệnh đề bổ nghĩa ＋ ふりをする', Explanation = N'Tỏ ra đang làm, biết hoặc cảm thấy điều gì để người khác tin như vậy.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to pretend; to act as if; to put on an act of ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to pretend; to act as if; to put on an act of ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［plain form］／い-adjective＋ ふりをする
な-adjective＋ な／Noun＋ の ＋ ふりをする' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［plain form］／い-adjective＋ ふりをする
な-adjective＋ な／Noun＋ の ＋ ふりをする') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ふりをする means to pretend or put on an act — to behave as if something were true when it isn''t. 寝ているふりをする = pretend to be asleep; 知らないふりをする = pretend not to know. Verbs and い-adjectives attach plainly, while nouns and な-adjectives take の／な first.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ふりをする means to pretend or put on an act — to behave as if something were true when it isn''t. 寝ているふりをする = pretend to be asleep; 知らないふりをする = pretend not to know. Verbs and い-adjectives attach plainly, while nouns and な-adjectives take の／な first.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Use the ない form to pretend NOT to do something: 気づかないふりをする = pretend not to notice.
Nouns and な-adjectives take の／な before ふり: 病気のふりをする, 元気なふりをする.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Use the ない form to pretend NOT to do something: 気づかないふりをする = pretend not to notice.
Nouns and な-adjectives take の／な before ふり: 病気のふりをする, 元気なふりをする.');
SET @Parents += @@ROWCOUNT;
