-- N3-G-042.json: beki-da
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'beki-da' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'beki-da');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: beki-da', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'べきだ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'べきだ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'べきだ' AND DATALENGTH(c.Reading) = DATALENGTH(N'べきだ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Nên, cần phải', Formation = N'Động từ thể từ điển ＋ べきだ (する → するべき／すべき)', Explanation = N'Nêu điều nên làm theo trách nhiệm hoặc cách ứng xử được cho là đúng.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'should; ought to (the right or proper thing to do)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'should; ought to (the right or proper thing to do)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ べきだ
する → するべき／すべき' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ べきだ
する → するべき／すべき') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'べきだ says something is the right, proper, or expected thing to do — a firm sense of what one ought to do, based on principle or common sense. It attaches to the dictionary form of a verb. With する, both するべき and すべき are used.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'べきだ says something is the right, proper, or expected thing to do — a firm sense of what one ought to do, based on principle or common sense. It attaches to the dictionary form of a verb. With する, both するべき and すべき are used.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'べきだ is stronger and more principled than 方がいい; it states what is right, not just a gentle suggestion.
Don''t use べき for unavoidable rules or natural necessity (''you must be over 18'') — that is なければならない; べき is about what is proper.
With する, both するべき and すべき are accepted.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'べきだ is stronger and more principled than 方がいい; it states what is right, not just a gentle suggestion.
Don''t use べき for unavoidable rules or natural necessity (''you must be over 18'') — that is なければならない; べき is about what is proper.
With する, both するべき and すべき are accepted.');
SET @Parents += @@ROWCOUNT;
