AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'beki-da:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'beki-da:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'約束したのだから、最後まで責任を持つべきだ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'約束したのだから、最後まで責任を持つべきだ。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
