AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'beki-da:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'beki-da:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'体調が悪いなら、無理をせず休むべきだよ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'体調が悪いなら、無理をせず休むべきだよ。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
