IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ほど〜ない' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ほど〜ない') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ほど〜ない' AND DATALENGTH(c.Reading) = DATALENGTH(N'ほど〜ない') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Không… bằng, không… như', Formation = N'Mốc so sánh ＋ ほど ＋ vị ngữ phủ định', Explanation = N'Cho biết mức độ thực tế thấp hơn mốc được nêu.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'not as ~ as; not to the extent of ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'not as ~ as; not to the extent of ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun＋ ほど ＋ ［negative predicate］' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun＋ ほど ＋ ［negative predicate］') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'In 〜ほど〜ない, the noun before ほど is a standard you fall short of: A は B ほど〜ない = ''A is not as ... as B.'' B is the higher one, and A doesn''t reach it. It always ends in a negative.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'In 〜ほど〜ない, the noun before ほど is a standard you fall short of: A は B ほど〜ない = ''A is not as ... as B.'' B is the higher one, and A doesn''t reach it. It always ends in a negative.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The item after ほど is the higher standard: A は B ほど〜ない means A falls short of B, so B is the greater one.
It requires a negative ending; drop the negative and ほど no longer means ''not as... as''.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The item after ほど is the higher standard: A は B ほど〜ない means A falls short of B, so B is the greater one.
It requires a negative ending; drop the negative and ほど no longer means ''not as... as''.');
