AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'masaka' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'masaka');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: masaka', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'まさか' AND DATALENGTH(c.Pattern) = DATALENGTH(N'まさか') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'まさか' AND DATALENGTH(c.Reading) = DATALENGTH(N'まさか') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Không ngờ, không thể nào', Formation = N'まさか ＋ mệnh đề (thường có とは／なんて)', Explanation = N'Diễn tả sự ngạc nhiên trước điều rất khó tin hoặc ngoài dự đoán.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
