IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'もの・もん' AND DATALENGTH(c.Pattern) = DATALENGTH(N'もの・もん') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'もの・もん' AND DATALENGTH(c.Reading) = DATALENGTH(N'もの・もん') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Vì… mà, tại… mà', Formation = N'Mệnh đề ＋ もの／もん (danh từ và tính từ な thường dùng だ)', Explanation = N'Nêu lý do mang tính cá nhân, đôi khi có sắc thái phân trần. もん thân mật hơn.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'because ~ (a reason given emotionally, often as an excuse)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'because ~ (a reason given emotionally, often as an excuse)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence［plain form］＋ もの／もん' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence［plain form］＋ もの／もん') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Sentence-final もの (casual もん) gives a reason with feeling — justifying, excusing, or grumbling. It often answers a ''why?'' and pairs with だって at the start of the reply. The tone is casual and can sound childish or defensive.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Sentence-final もの (casual もん) gives a reason with feeling — justifying, excusing, or grumbling. It often answers a ''why?'' and pairs with だって at the start of the reply. The tone is casual and can sound childish or defensive.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'This is emotive, casual reason-giving; it''s out of place in polite or formal speech.
It frequently follows a だって opener: 「だって〜だもん」.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'This is emotive, casual reason-giving; it''s out of place in polite or formal speech.
It frequently follows a だって opener: 「だって〜だもん」.');
