IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ようがない' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ようがない') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ようがない' AND DATALENGTH(c.Reading) = DATALENGTH(N'ようがない') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Không có cách nào làm', Formation = N'Gốc ます ＋ ようがない', Explanation = N'Nêu rằng thiếu phương tiện, điều kiện hoặc cách thực hiện.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'there''s no way to ~; it''s impossible to ~ (no means available)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'there''s no way to ~; it''s impossible to ~ (no means available)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ ようがない／ようもない' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ ようがない／ようもない') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'The ます-stem plus ようがない says there is no method or means to do something, so it simply can''t be done — 連絡しようがない = there''s no way to get in touch. It stresses a missing means rather than a lack of ability. Also written 〜ようもない.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'The ます-stem plus ようがない says there is no method or means to do something, so it simply can''t be done — 連絡しようがない = there''s no way to get in touch. It stresses a missing means rather than a lack of ability. Also written 〜ようもない.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Attach it to the stem: 直しようがない, not 直すようがない.
