IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ようとしたが' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ようとしたが') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ようとしたが' AND DATALENGTH(c.Reading) = DATALENGTH(N'ようとしたが') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Định… nhưng, đã cố… nhưng', Formation = N'Động từ thể ý hướng ＋ としたが', Explanation = N'Nêu ý định hoặc nỗ lực thực hiện ngay trước trở ngại.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'was about to / tried to ~, but ~ (and it didn''t work out)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'was about to / tried to ~, but ~ (and it didn''t work out)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［volitional］＋ とした ＋ が／けれど、Sentence' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［volitional］＋ とした ＋ が／けれど、Sentence') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'The past volitional 〜ようとした plus が／けど marks that you were on the verge of doing something, or attempted it, but were interrupted or it failed — 出ようとしたが = I was about to leave, but... Because of が, a thwarted outcome usually follows.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'The past volitional 〜ようとした plus が／けど marks that you were on the verge of doing something, or attempted it, but were interrupted or it failed — 出ようとしたが = I was about to leave, but... Because of が, a thwarted outcome usually follows.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Built on the volitional (出よう, 言おう), not the dictionary form.
