FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'putting (feeling or effort) into; filled with ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'putting (feeling or effort) into; filled with ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun［feeling word］＋ を込めて' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun［feeling word］＋ を込めて') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'を込めて attaches to a noun naming a feeling or energy and says the following action is carried out with that feeling poured into it — 心を込めて = with all one''s heart, 感謝を込めて = with gratitude. The noun names the emotion or effort that fills the act.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'を込めて attaches to a noun naming a feeling or energy and says the following action is carried out with that feeling poured into it — 心を込めて = with all one''s heart, 感謝を込めて = with gratitude. The noun names the emotion or effort that fills the act.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The noun names a feeling or energy put into the act (心, 愛, 感謝, 願い); it is not used for physically filling a container with something.
Don''t mix it up with だらけ (''covered in / full of''), which describes a surface littered with something unwanted; を込めて is about pouring emotion into an action, even though both can be glossed ''full of''.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The noun names a feeling or energy put into the act (心, 愛, 感謝, 願い); it is not used for physically filling a container with something.
Don''t mix it up with だらけ (''covered in / full of''), which describes a surface littered with something unwanted; を込めて is about pouring emotion into an action, even though both can be glossed ''full of''.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Tôi viết thư cho mẹ để gửi gắm lòng biết ơn.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'o-komete:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'o-komete:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'母に感謝を込めて手紙を書きました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'母に感謝を込めて手紙を書きました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
