FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'o-komete:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'o-komete:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼女は心を込めて歌を歌った。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼女は心を込めて歌を歌った。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N3-G-049.json: o-chuushin-ni
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'o-chuushin-ni' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'o-chuushin-ni');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: o-chuushin-ni', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'を中心に' AND DATALENGTH(c.Pattern) = DATALENGTH(N'を中心に') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'をちゅうしんに' AND DATALENGTH(c.Reading) = DATALENGTH(N'をちゅうしんに') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Lấy… làm trung tâm, chủ yếu ở', Formation = N'Danh từ ＋ を中心に', Explanation = N'Nêu tâm điểm trong không gian hoặc nhóm chiếm phần chính.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'centered on; with ~ at the center; mainly among ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'centered on; with ~ at the center; mainly among ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ を中心に（して）
Noun ＋ を中心とした ＋ Noun' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ を中心に（して）
Noun ＋ を中心とした ＋ Noun') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'を中心に（して） marks the thing that sits at the center of some activity, group, or arrangement — everything else gathers around it or is organized with it as the focus. 駅を中心に = centered on the station; 若者を中心に = mainly among young people.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'を中心に（して） marks the thing that sits at the center of some activity, group, or arrangement — everything else gathers around it or is organized with it as the focus. 駅を中心に = centered on the station; 若者を中心に = mainly among young people.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'を中心に marks the focal point that other things arrange themselves around; it isn''t a plain ''about (a topic)'' — for simply discussing a subject, use について.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'を中心に marks the focal point that other things arrange themselves around; it isn''t a plain ''about (a topic)'' — for simply discussing a subject, use について.');
SET @Parents += @@ROWCOUNT;
