-- N3-G-049.json: o-tsuujite
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'o-tsuujite' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'o-tsuujite');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: o-tsuujite', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'を通じて・を通して' AND DATALENGTH(c.Pattern) = DATALENGTH(N'を通じて・を通して') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'をつうじて・をとおして' AND DATALENGTH(c.Reading) = DATALENGTH(N'をつうじて・をとおして') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Qua, thông qua, suốt', Formation = N'Danh từ ＋ を通じて／を通して', Explanation = N'Nêu phương tiện, người trung gian hoặc cả khoảng thời gian mà điều gì diễn ra.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'through; by way of; throughout' AND DATALENGTH(c.Meaning) = DATALENGTH(N'through; by way of; throughout') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ を通じて／を通して' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ を通じて／を通して') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'を通じて / を通して marks a medium or intermediary that something passes through — a person, a channel, an experience — or a whole span of time or area over which something holds. 友達を通じて = through a friend; 一年を通して = all year round.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'を通じて / を通して marks a medium or intermediary that something passes through — a person, a channel, an experience — or a whole span of time or area over which something holds. 友達を通じて = through a friend; 一年を通して = all year round.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Two senses share the form: with a person or means it reads ''by way of'', with a time span or area it reads ''throughout''; the noun tells you which.
を通して leans slightly toward actively using the means, を通じて slightly toward the result or the span, but they overlap and are often interchangeable.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Two senses share the form: with a person or means it reads ''by way of'', with a time span or area it reads ''throughout''; the noun tells you which.
を通して leans slightly toward actively using the means, を通じて slightly toward the result or the span, but they overlap and are often interchangeable.');
SET @Parents += @@ROWCOUNT;
