BEGIN
UPDATE c SET Meaning = N'Đừng làm, không được làm', Formation = N'Động từ thể từ điển ＋ んじゃない（よ）', Explanation = N'Dùng cuối câu với giọng dứt khoát để cấm hoặc nhắc đừng làm.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'don''t ~! (blunt, casual prohibition)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'don''t ~! (blunt, casual prohibition)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ んじゃない（よ）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ んじゃない（よ）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Attached to a verb in the dictionary form, 〜んじゃない（よ） is a forceful, spoken way to tell someone not to do something — the tone a parent might use scolding a child. 泣くんじゃない = Don''t cry! It is blunter and more emotional than a flat 〜てはいけない.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Attached to a verb in the dictionary form, 〜んじゃない（よ） is a forceful, spoken way to tell someone not to do something — the tone a parent might use scolding a child. 泣くんじゃない = Don''t cry! It is blunter and more emotional than a flat 〜てはいけない.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Keep this apart from the suggestion 〜んじゃない（？） (''isn''t it ~?; I''d say ~''), which sits on the plain form with a rising, questioning tone; as a prohibition it takes the dictionary form and a falling, commanding tone.
With the past た form, 〜んじゃなかった flips to regret (''I shouldn''t have ~'', 食べるんじゃなかった = I wish I hadn''t eaten it), not a command.
It is rough, casual speech; don''t aim it at superiors — use 〜ないでください instead.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Keep this apart from the suggestion 〜んじゃない（？） (''isn''t it ~?; I''d say ~''), which sits on the plain form with a rising, questioning tone; as a prohibition it takes the dictionary form and a falling, commanding tone.
With the past た form, 〜んじゃなかった flips to regret (''I shouldn''t have ~'', 食べるんじゃなかった = I wish I hadn''t eaten it), not a command.
It is rough, casual speech; don''t aim it at superiors — use 〜ないでください instead.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Nguy hiểm lắm, đừng leo lên chỗ cao như vậy.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'n-janai:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'n-janai:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'危ないから、そんな高いところに登るんじゃない。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'危ないから、そんな高いところに登るんじゃない。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Đừng tự tiện dùng đồ của người khác.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'n-janai:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'n-janai:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'人の物を勝手に使うんじゃないよ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'人の物を勝手に使うんじゃないよ。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N3-G-050.json: ndatte
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'ndatte' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'ndatte');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ndatte', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'んだって' AND DATALENGTH(c.Pattern) = DATALENGTH(N'んだって') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'んだって' AND DATALENGTH(c.Reading) = DATALENGTH(N'んだって') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Nghe nói, nghe đâu (thân mật)', Formation = N'Động từ hoặc tính từ い ở thể thông thường ＋ んだって
Danh từ hoặc gốc tính từ な ＋ なんだって (ở dạng khẳng định hiện tại)', Explanation = N'Dùng cuối câu để kể lại điều người nói nghe được trong giao tiếp thân mật. Mẫu này kết hợp んだ, dạng nói của のだ, với trợ từ trích dẫn って.', UsageNotes = N'学生なんだって nghĩa là nghe nói người đó là học sinh hoặc sinh viên. だって đứng đầu câu có thể dùng để phân trần. Trong văn phong trung tính hơn, có thể dùng そうだ để thuật lại thông tin.', UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'I hear that ~; apparently ~ (casual, spoken hearsay)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'I hear that ~; apparently ~ (casual, spoken hearsay)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb／い-adjective［plain form］ ＋ んだって
な-adjective／Noun ＋ な ＋ んだって' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb／い-adjective［plain form］ ＋ んだって
な-adjective／Noun ＋ な ＋ んだって') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜んだって passes along something you heard as casual, spoken news or gossip — ''apparently'', ''I hear''. It is built from the explanatory のだ (→ んだ) plus the quoting って, so it reports the information with a ''the story is that ~'' flavor. 田中さん、結婚するんだって = Apparently Tanaka is getting married.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜んだって passes along something you heard as casual, spoken news or gossip — ''apparently'', ''I hear''. It is built from the explanatory のだ (→ んだ) plus the quoting って, so it reports the information with a ''the story is that ~'' flavor. 田中さん、結婚するんだって = Apparently Tanaka is getting married.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'After a noun or な-adjective, insert な: 学生なんだって, 静かなんだって — not 学生だんだって.
Don''t confuse it with sentence-initial だって (''because; but; after all''); 〜んだって sits at the end of the clause and reports hearsay.
It is colloquial; for neutral or written reporting of what you heard, use 〜そうだ instead.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'After a noun or な-adjective, insert な: 学生なんだって, 静かなんだって — not 学生だんだって.
Don''t confuse it with sentence-initial だって (''because; but; after all''); 〜んだって sits at the end of the clause and reports hearsay.
It is colloquial; for neutral or written reporting of what you heard, use 〜そうだ instead.');
SET @Parents += @@ROWCOUNT;
