WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'a8a06b3e15' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'a8a06b3e15');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: a8a06b3e15', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'男の人' AND DATALENGTH(c.Word) = DATALENGTH(N'男の人') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'おとこのひと' AND DATALENGTH(c.Reading) = DATALENGTH(N'おとこのひと') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Người đàn ông', PartOfSpeech = N'Cụm từ, Danh từ', Explanation = N'男の人（おとこのひと）có nghĩa là người đàn ông.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'man' AND DATALENGTH(c.Meaning) = DATALENGTH(N'man') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'exp, n' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'exp, n') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
SET @Parents += @@ROWCOUNT;
