AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'148779' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'148779') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'若い男の人がドアの前で歌っています。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'若い男の人がドアの前で歌っています。')
