IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'ざっと' AND DATALENGTH(c.Word) = DATALENGTH(N'ざっと') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ざっと' AND DATALENGTH(c.Reading) = DATALENGTH(N'ざっと') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
