AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'9fc5f5ca7f' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'9fc5f5ca7f');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: 9fc5f5ca7f', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'様々' AND DATALENGTH(c.Word) = DATALENGTH(N'様々') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'さまざま' AND DATALENGTH(c.Reading) = DATALENGTH(N'さまざま') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
