FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'varied; various' AND DATALENGTH(c.Meaning) = DATALENGTH(N'varied; various') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'adj-na, n' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'adj-na, n') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
