WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'0894c700f3' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'0894c700f3');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: 0894c700f3', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'直' AND DATALENGTH(c.Word) = DATALENGTH(N'直') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'じき' AND DATALENGTH(c.Reading) = DATALENGTH(N'じき') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
