FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'soon; in a moment; before long; shortly' AND DATALENGTH(c.Meaning) = DATALENGTH(N'soon; in a moment; before long; shortly') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'adj-na, adv, n' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'adj-na, adv, n') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
