IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'で' AND DATALENGTH(c.Word) = DATALENGTH(N'で') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'で' AND DATALENGTH(c.Reading) = DATALENGTH(N'で') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Sự đi ra, chảy ra; người xuất thân hoặc tốt nghiệp từ một nơi', PartOfSpeech = N'Danh từ, hậu tố', Explanation = N'出（で）là danh từ chỉ sự đi ra hoặc dòng chảy ra. Khi đứng sau tên nơi chốn hay trường học, nó chỉ người xuất thân hoặc tốt nghiệp từ nơi đó.', UsageNotes = N'Ví dụ dùng đúng nghĩa của mục này gồm 水の出が悪い (nước chảy yếu) và 大学出 (người tốt nghiệp đại học). Hai câu ví dụ từ nguồn dùng trợ từ で hoặc mẫu ～ないで.', UpdatedAt = SYSUTCDATETIME()
