IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'便' AND DATALENGTH(c.Word) = DATALENGTH(N'便') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'びん' AND DATALENGTH(c.Reading) = DATALENGTH(N'びん') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Chuyến xe, chuyến bay hoặc chuyến tàu; dịch vụ vận tải', PartOfSpeech = N'Danh từ, hậu tố', Explanation = N'便 đọc là びん khi chỉ chuyến hoặc dịch vụ vận tải. Trong バスの便, từ này nói về dịch vụ xe buýt và mức thuận tiện của việc đi lại.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
