AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'a6c8fd99d7' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'a6c8fd99d7');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: a6c8fd99d7', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'夢中' AND DATALENGTH(c.Word) = DATALENGTH(N'夢中') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'むちゅう' AND DATALENGTH(c.Reading) = DATALENGTH(N'むちゅう') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
