WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'3fc07b1856' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'3fc07b1856');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: 3fc07b1856', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'我々' AND DATALENGTH(c.Word) = DATALENGTH(N'我々') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'われわれ' AND DATALENGTH(c.Reading) = DATALENGTH(N'われわれ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N3' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N3'))
BEGIN
UPDATE c SET Meaning = N'Chúng tôi, chúng ta', PartOfSpeech = N'Đại từ', Explanation = N'我々（われわれ）có nghĩa là chúng tôi, chúng ta.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'we' AND DATALENGTH(c.Meaning) = DATALENGTH(N'we') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'pn' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'pn') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
SET @Parents += @@ROWCOUNT;
