AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'216245' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'216245') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'しかし我々は彼なしで続行した。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'しかし我々は彼なしで続行した。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
