IF @Matches > 1 THROW 51001, 'Ambiguous translation source: owaru', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'〜終わる' AND DATALENGTH(c.Pattern) = DATALENGTH(N'〜終わる') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'〜おわる' AND DATALENGTH(c.Reading) = DATALENGTH(N'〜おわる') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Làm xong, làm hết', Formation = N'Gốc ます ＋ 終わる', Explanation = N'Đánh dấu một hành động đã hoặc sẽ được làm đến hết, như 読み終わる là đọc xong.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to finish doing (an action all the way through)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to finish doing (an action all the way through)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ 終わる' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ 終わる') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜終わる attaches to the ます-stem of a verb to say you finish doing that action completely — 食べ終わる = finish eating, 読み終わる = finish reading. The whole compound conjugates like an ordinary る-verb (終わった, 終わって). Use it to mark the point where an action you are carrying out is done.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜終わる attaches to the ます-stem of a verb to say you finish doing that action completely — 食べ終わる = finish eating, 読み終わる = finish reading. The whole compound conjugates like an ordinary る-verb (終わった, 終わって). Use it to mark the point where an action you are carrying out is done.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Attach it to the stem, not the dictionary form: 書き終わる, not 書く終わる.
This compound is about finishing an action someone performs; when a situation ends on its own (会議が終わる = the meeting ends), 終わる is just an ordinary verb, not this stem-compound.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Attach it to the stem, not the dictionary form: 書き終わる, not 書く終わる.
This compound is about finishing an action someone performs; when a situation ends on its own (会議が終わる = the meeting ends), 終わる is just an ordinary verb, not this stem-compound.');
SET @Parents += @@ROWCOUNT;
