AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'gari' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'gari');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: gari', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'〜がり' AND DATALENGTH(c.Pattern) = DATALENGTH(N'〜がり') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'〜がり' AND DATALENGTH(c.Reading) = DATALENGTH(N'〜がり') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Người hay cảm thấy, người nhạy với điều gì', Formation = N'Bỏ い của tính từ đuôi い ＋ がり', Explanation = N'寒がり chỉ người dễ thấy lạnh, còn 寂しがり chỉ người dễ thấy cô đơn. Dạng này tạo danh từ chỉ đặc điểm thường thấy.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'a person who readily feels ~; sensitive to ~ (personality trait)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'a person who readily feels ~; sensitive to ~ (personality trait)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'い-adjective［stem, feeling word］＋ がり（や）' AND DATALENGTH(c.Formation) = DATALENGTH(N'い-adjective［stem, feeling word］＋ がり（や）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜がり turns a feeling-adjective into a noun for a person who is prone to feeling that way — 寒がり = someone who feels the cold easily, 寂しがり = someone who gets lonely easily. It describes a lasting personality trait, and often takes や on the end (寒がりや). The base is an adjective of emotion or sensation.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜がり turns a feeling-adjective into a noun for a person who is prone to feeling that way — 寒がり = someone who feels the cold easily, 寂しがり = someone who gets lonely easily. It describes a lasting personality trait, and often takes や on the end (寒がりや). The base is an adjective of emotion or sensation.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It pairs with adjectives of feeling or sensation (寒い, 怖い, 寂しい, 恥ずかしい), not with just any adjective.
Drop the final い before adding がり: 寒い → 寒がり, not 寒いがり.
It labels a habitual trait, not how someone feels at this moment; for ''I''m cold right now'' just say 寒い.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It pairs with adjectives of feeling or sensation (寒い, 怖い, 寂しい, 恥ずかしい), not with just any adjective.
Drop the final い before adding がり: 寒い → 寒がり, not 寒いがり.
It labels a habitual trait, not how someone feels at this moment; for ''I''m cold right now'' just say 寒い.');
