AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'no-darou-ka:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'no-darou-ka:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼は本当のことを話しているのだろうか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼は本当のことを話しているのだろうか。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
