AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'no-darou-ka:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'no-darou-ka:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'こんなに勉強して、試験に受かるのだろうか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'こんなに勉強して、試験に受かるのだろうか。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
