END ELSE SET @Skipped += 1;
-- N4-G-004.json: wa-no-hitotsu-da
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'wa-no-hitotsu-da' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'wa-no-hitotsu-da');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: wa-no-hitotsu-da', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'～は～の一つだ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'～は～の一つだ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'～は～のひとつだ' AND DATALENGTH(c.Reading) = DATALENGTH(N'～は～のひとつだ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Là một trong số…', Formation = N'A ＋ は ＋ nhóm ＋ の一つだ／の一人だ', Explanation = N'Xếp A vào một tập hợp. Dùng 一つ với sự vật hoặc địa điểm, dùng 一人 với người.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'~ is one of (several / many) ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'~ is one of (several / many) ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun［X］＋ は ＋ Noun［Y, group］＋ の一つだ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun［X］＋ は ＋ Noun［Y, group］＋ の一つだ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜は〜の一つだ presents one thing as a member of a larger group — ''X is one of the Y''. 京都は人気のある町の一つだ = Kyoto is one of the popular cities. It''s a simple, natural way to place something among many of its kind rather than singling it out as the only one.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜は〜の一つだ presents one thing as a member of a larger group — ''X is one of the Y''. 京都は人気のある町の一つだ = Kyoto is one of the popular cities. It''s a simple, natural way to place something among many of its kind rather than singling it out as the only one.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The group noun before 一つ is plural in sense, so a describing phrase usually comes first: 世界で一番大きい国の一つ = one of the biggest countries in the world.
一つ counts things; for people, use 〜の一人 (ひとり) instead — 優秀な学生の一人だ = one of the excellent students.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The group noun before 一つ is plural in sense, so a describing phrase usually comes first: 世界で一番大きい国の一つ = one of the biggest countries in the world.
一つ counts things; for people, use 〜の一人 (ひとり) instead — 優秀な学生の一人だ = one of the excellent students.');
SET @Parents += @@ROWCOUNT;
