AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'wa-no-hitotsu-da:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'wa-no-hitotsu-da:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼は、クラスで最も背が高い学生のひとりです。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼は、クラスで最も背が高い学生のひとりです。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
