IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'～風' AND DATALENGTH(c.Pattern) = DATALENGTH(N'～風') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'～ふう' AND DATALENGTH(c.Reading) = DATALENGTH(N'～ふう') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Theo kiểu, mang phong cách', Formation = N'Danh từ ＋ 風（ふう）', Explanation = N'Hậu tố 風 chỉ kiểu hoặc phong cách. Sau đó có thể thêm の để bổ nghĩa danh từ, hoặc に để bổ nghĩa động từ.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'-style; -like; in the manner of ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'-style; -like; in the manner of ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ 風' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ 風') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜風 after a noun means ''in the style of'' or ''-like'' — 日本風 = Japanese-style, ヨーロッパ風 = European-style. It says something resembles or imitates that thing''s manner or appearance, without necessarily being the real, authentic article.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜風 after a noun means ''in the style of'' or ''-like'' — 日本風 = Japanese-style, ヨーロッパ風 = European-style. It says something resembles or imitates that thing''s manner or appearance, without necessarily being the real, authentic article.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'In this ''style'' meaning 〜風 is read ふう (和風 = わふう); don''t read it かぜ (''wind'') here.
It describes a resemblance or imitation, not the genuine thing: 日本風の料理 is food made in a Japanese style, which may not be authentically Japanese.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'In this ''style'' meaning 〜風 is read ふう (和風 = わふう); don''t read it かぜ (''wind'') here.
It describes a resemblance or imitation, not the genuine thing: 日本風の料理 is food made in a Japanese style, which may not be authentically Japanese.');
SET @Parents += @@ROWCOUNT;
