IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'～ら' AND DATALENGTH(c.Pattern) = DATALENGTH(N'～ら') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'～ら' AND DATALENGTH(c.Reading) = DATALENGTH(N'～ら') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Hậu tố chỉ số nhiều hoặc nhóm người', Formation = N'Đại từ hay từ chỉ người ＋ ら', Explanation = N'Tạo từ chỉ nhóm, như 僕ら là chúng tôi hoặc chúng ta, 彼ら là họ. Sắc thái tùy từ đứng trước và hoàn cảnh.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'casual pluralizing suffix (僕ら = we, 彼ら = they)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'casual pluralizing suffix (僕ら = we, 彼ら = they)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun［person・pronoun］＋ ら' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun［person・pronoun］＋ ら') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'〜ら is a casual pluralizing suffix attached to people-words and pronouns — 僕ら = we, 彼ら = they, 君ら = you (plural). It can also group demonstratives (これら = these). It sounds more informal and blunt than 〜たち.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'〜ら is a casual pluralizing suffix attached to people-words and pronouns — 僕ら = we, 彼ら = they, 君ら = you (plural). It can also group demonstratives (これら = these). It sounds more informal and blunt than 〜たち.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'〜ら is casual and can sound rough attached to names or to others; the neutral, polite plural is 〜たち (子どもたち).
Pointing it at other people can feel dismissive (お前ら, あいつら), so use it with care.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'〜ら is casual and can sound rough attached to names or to others; the neutral, polite plural is 〜たち (子どもたち).
Pointing it at other people can feel dismissive (お前ら, あいつら), so use it with care.');
