AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'aida:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'aida:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'夏休みのあいだ、毎日海で泳ぎました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'夏休みのあいだ、毎日海で泳ぎました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
