AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'aida:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'aida:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'赤ちゃんが寝ているあいだ、私はずっと本を読んでいました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'赤ちゃんが寝ているあいだ、私はずっと本を読んでいました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
