-- N4-G-005.json: aida-ni
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'aida-ni' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'aida-ni');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: aida-ni', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'間に' AND DATALENGTH(c.Pattern) = DATALENGTH(N'間に') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'あいだに' AND DATALENGTH(c.Reading) = DATALENGTH(N'あいだに') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Trong lúc, vào một thời điểm trong khoảng', Formation = N'Danh từ ＋ の ＋ 間に／mệnh đề bổ nghĩa ＋ 間に', Explanation = N'Cho biết một việc diễn ra vào một thời điểm hoặc được hoàn thành trong khoảng đã nêu.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'while ~; at some point during ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'while ~; at some point during ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］いる ＋ 間に
Noun ＋ の ＋ 間に' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］いる ＋ 間に
Noun ＋ の ＋ 間に') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'間に sets a period of time and says the main action happens at some moment inside it, not across the whole thing. It is the ''catch the chance while ~'' pattern: 出かけている間に電話が来た = a call came while I was out. The に pins the main event to a point within the period.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'間に sets a period of time and says the main action happens at some moment inside it, not across the whole thing. It is the ''catch the chance while ~'' pattern: 出かけている間に電話が来た = a call came while I was out. The に pins the main event to a point within the period.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'間に = one event at a point inside the period; plain 間 (no に) = the main action lasts the whole period. 昼休みの間に食べた (ate at some point during the break) vs 昼休みの間ずっと食べていた (kept eating the whole break).
The main clause is usually a single, completed event (掃除した, 電話が来た), not a state that runs the whole time.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'間に = one event at a point inside the period; plain 間 (no に) = the main action lasts the whole period. 昼休みの間に食べた (ate at some point during the break) vs 昼休みの間ずっと食べていた (kept eating the whole break).
The main clause is usually a single, completed event (掃除した, 電話が来た), not a state that runs the whole time.');
SET @Parents += @@ROWCOUNT;
