AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'aida-ni:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'aida-ni:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'昼休みのあいだに、少し買い物をしてきました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'昼休みのあいだに、少し買い物をしてきました。')
