IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'後で' AND DATALENGTH(c.Pattern) = DATALENGTH(N'後で') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'あとで' AND DATALENGTH(c.Reading) = DATALENGTH(N'あとで') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Sau khi, sau đó', Formation = N'Động từ thể た ＋ 後で／danh từ ＋ の ＋ 後で', Explanation = N'Đặt hành động hoặc mốc làm trước trước 後で, rồi nêu việc diễn ra sau.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'after (doing); later' AND DATALENGTH(c.Meaning) = DATALENGTH(N'after (doing); later') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［た form］ ＋ 後で
Noun ＋ の ＋ 後で' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［た form］ ＋ 後で
Noun ＋ の ＋ 後で') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'後で says one thing happens after another. Put the earlier action in the past (た) form before it (食べた後で = after eating), or a noun plus の (食事の後で = after the meal). On its own, 後で simply means ''later'': 後で電話します = I''ll call later.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'後で says one thing happens after another. Put the earlier action in the past (た) form before it (食べた後で = after eating), or a noun plus の (食事の後で = after the meal). On its own, 後で simply means ''later'': 後で電話します = I''ll call later.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Use the past (た) form before 後で even for future plans: 帰った後で, not 帰る後で.
後で just orders the two events in time. If you want to stress ''and only after that'', 〜てから carries that ''once ~ is done'' feeling more strongly.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Use the past (た) form before 後で even for future plans: 帰った後で, not 帰る後で.
後で just orders the two events in time. If you want to stress ''and only after that'', 〜てから carries that ''once ~ is done'' feeling more strongly.');
SET @Parents += @@ROWCOUNT;
