AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'ika:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'ika:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'12歳以下のお子さんは半額です。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'12歳以下のお子さんは半額です。')
