BEGIN
UPDATE c SET Meaning = N'Liệu có… hay không', Formation = N'Thể thông thường ＋ かどうか (danh từ và tính từ な thường bỏ だ)', Explanation = N'Đưa câu hỏi có hoặc không vào bên trong câu lớn hơn, thường đi với động từ chỉ biết, hỏi hoặc kiểm tra.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
