WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'garu-gatteiru' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'garu-gatteiru');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: garu-gatteiru', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'がる・がっている' AND DATALENGTH(c.Pattern) = DATALENGTH(N'がる・がっている') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'がる・がっている' AND DATALENGTH(c.Reading) = DATALENGTH(N'がる・がっている') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Tỏ ra, biểu lộ cảm xúc hay mong muốn', Formation = N'Bỏ い của tính từ い hoặc たい ＋ がる／gốc tính từ な ＋ がる', Explanation = N'Dùng khi nói về cảm xúc hoặc mong muốn của người khác dựa trên biểu hiện. がっている thường chỉ biểu hiện đang quan sát được, còn がる có thể chỉ khuynh hướng.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to show signs of; to seem to feel (someone else''s emotion)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to show signs of; to seem to feel (someone else''s emotion)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'い-adjective［stem］／〜たい［stem］＋ がる／がっている' AND DATALENGTH(c.Formation) = DATALENGTH(N'い-adjective［stem］／〜たい［stem］＋ がる／がっている') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'がる attaches to the stem of feeling-adjectives (欲しい→欲しがる, 寂しい→寂しがる) and to 〜たい (食べたい→食べたがる) to describe someone else outwardly showing that feeling. がっている is the ongoing ''is showing it right now'' form. It lets you talk about a third person''s emotions, which you can only observe from the outside.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'がる attaches to the stem of feeling-adjectives (欲しい→欲しがる, 寂しい→寂しがる) and to 〜たい (食べたい→食べたがる) to describe someone else outwardly showing that feeling. がっている is the ongoing ''is showing it right now'' form. It lets you talk about a third person''s emotions, which you can only observe from the outside.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Use がる for other people''s feelings, not your own: 私は欲しい, but 彼は欲しがっている.
The wanted thing takes を with 欲しがる, not が: おもちゃを欲しがる, not おもちゃが欲しがる.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Use がる for other people''s feelings, not your own: 私は欲しい, but 彼は欲しがっている.
The wanted thing takes を with 欲しがる, not が: おもちゃを欲しがる, not おもちゃが欲しがる.');
SET @Parents += @@ROWCOUNT;
