AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'garu-gatteiru:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'garu-gatteiru:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'子どもが新しいおもちゃを欲しがっています。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'子どもが新しいおもちゃを欲しがっています。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Em trai tôi rất sợ chó.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'garu-gatteiru:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'garu-gatteiru:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'弟は犬をとても怖がります。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'弟は犬をとても怖がります。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N4-G-010.json: kikoeru
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'kikoeru' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'kikoeru');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: kikoeru', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'聞こえる' AND DATALENGTH(c.Pattern) = DATALENGTH(N'聞こえる') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'きこえる' AND DATALENGTH(c.Reading) = DATALENGTH(N'きこえる') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Nghe thấy, vọng đến tai', Formation = N'Âm thanh ＋ が ＋ 聞こえる', Explanation = N'Nêu âm thanh tự lọt vào tai. 聞こえてくる nhấn mạnh âm thanh vọng đến từ một nơi khác.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to be audible; can hear (spontaneously)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to be audible; can hear (spontaneously)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ が ＋ 聞こえる' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ が ＋ 聞こえる') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'聞こえる means a sound reaches your ears on its own, without you trying to listen — ''can hear'' in the sense of ''is audible''. The sound is marked with が: 音が聞こえる. It''s the hearing partner of 見える, and it''s distinct from 聞ける, which is about having the chance or ability to listen to something on purpose.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'聞こえる means a sound reaches your ears on its own, without you trying to listen — ''can hear'' in the sense of ''is audible''. The sound is marked with が: 音が聞こえる. It''s the hearing partner of 見える, and it''s distinct from 聞ける, which is about having the chance or ability to listen to something on purpose.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'聞こえる = sound reaches you involuntarily; 聞ける = you get the chance/ability to listen on purpose (a concert, a recording).
Mark the sound with が, not を: 音が聞こえる, not 音を聞こえる.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'聞こえる = sound reaches you involuntarily; 聞ける = you get the chance/ability to listen on purpose (a concert, a recording).
Mark the sound with が, not を: 音が聞こえる, not 音を聞こえる.');
SET @Parents += @@ROWCOUNT;
