AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'gimonshi-ka' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'gimonshi-ka');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: gimonshi-ka', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'疑問詞＋か' AND DATALENGTH(c.Pattern) = DATALENGTH(N'疑問詞＋か') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ぎもんしか' AND DATALENGTH(c.Reading) = DATALENGTH(N'ぎもんしか') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Câu hỏi gián tiếp có từ để hỏi', Formation = N'Từ để hỏi ＋ mệnh đề thể thông thường ＋ か', Explanation = N'Đặt câu hỏi như ở đâu, cái gì hoặc khi nào vào bên trong một câu khác. Sau か có thể dùng 知る, 決める hoặc động từ phù hợp khác.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'embedded question with a question word' AND DATALENGTH(c.Meaning) = DATALENGTH(N'embedded question with a question word') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'疑問詞（どこ・だれ・何…）＋ … ＋ か ＋ Verb' AND DATALENGTH(c.Formation) = DATALENGTH(N'疑問詞（どこ・だれ・何…）＋ … ＋ か ＋ Verb') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'A question word (どこ・だれ・何・いつ・どう…) plus か wraps a wh-question into a noun-like clause that a larger sentence can act on: どこに行くか分からない = I don''t know where to go. The main verb (know, ask, decide, tell…) then works on that embedded question. It''s the wh-question partner of かどうか.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'A question word (どこ・だれ・何・いつ・どう…) plus か wraps a wh-question into a noun-like clause that a larger sentence can act on: どこに行くか分からない = I don''t know where to go. The main verb (know, ask, decide, tell…) then works on that embedded question. It''s the wh-question partner of かどうか.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Before か, a noun or な-adjective drops だ: だれの本か分からない, not だれの本だか分からない.
Use this when there''s a question word. For a yes/no question with no such word, switch to かどうか.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Before か, a noun or な-adjective drops だ: だれの本か分からない, not だれの本だか分からない.
Use this when there''s a question word. For a yes/no question with no such word, switch to かどうか.');
SET @Parents += @@ROWCOUNT;
