IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ku-ni', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'く・に' AND DATALENGTH(c.Pattern) = DATALENGTH(N'く・に') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'く・に' AND DATALENGTH(c.Reading) = DATALENGTH(N'く・に') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Chuyển tính từ thành trạng từ', Formation = N'Tính từ い: bỏ い ＋ く／tính từ な: gốc ＋ に', Explanation = N'Dạng く hoặc に bổ nghĩa cho động từ để nêu cách hành động diễn ra. いい chuyển thành よく.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'turning adjectives into adverbs (〜く / 〜に)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'turning adjectives into adverbs (〜く / 〜に)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'い-adjective［stem］＋ く ＋ Verb
な-adjective ＋ に ＋ Verb' AND DATALENGTH(c.Formation) = DATALENGTH(N'い-adjective［stem］＋ く ＋ Verb
な-adjective ＋ に ＋ Verb') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'To describe how an action is done, adjectives take an adverb form. An い-adjective changes its final い to く (早い→早く), and a な-adjective adds に (静か→静かに). The result modifies a verb: 早く起きる = get up early, 静かに歩く = walk quietly.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'To describe how an action is done, adjectives take an adverb form. An い-adjective changes its final い to く (早い→早く), and a な-adjective adds に (静か→静かに). The result modifies a verb: 早く起きる = get up early, 静かに歩く = walk quietly.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'い-adjectives use く, な-adjectives use に: 早く and 静かに, never 早に or 静かく.
いい is irregular: its adverb form is よく, not いく.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'い-adjectives use く, な-adjectives use に: 早く and 静かに, never 早に or 静かく.
いい is irregular: its adverb form is よく, not いく.');
