WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'sou-ni-sou-na' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'sou-ni-sou-na');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: sou-ni-sou-na', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'そうに・そうな' AND DATALENGTH(c.Pattern) = DATALENGTH(N'そうに・そうな') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'そうに・そうな' AND DATALENGTH(c.Reading) = DATALENGTH(N'そうに・そうな') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Trông có vẻ… khi làm, trông có vẻ…', Formation = N'Gốc động từ hoặc tính từ theo mẫu そうだ ＋ そうに ＋ động từ／cùng gốc ＋ そうな ＋ danh từ', Explanation = N'そうに bổ nghĩa cho hành động. そうな bổ nghĩa cho danh từ.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'~-looking; in a ~-seeming way' AND DATALENGTH(c.Meaning) = DATALENGTH(N'~-looking; in a ~-seeming way') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］／い-adjective［stem］／な-adjective ＋ そうな ＋ Noun
Verb［stem］／い-adjective［stem］／な-adjective ＋ そうに ＋ Verb' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］／い-adjective［stem］／な-adjective ＋ そうな ＋ Noun
Verb［stem］／い-adjective［stem］／な-adjective ＋ そうに ＋ Verb') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'The appearance そう conjugates like a な-adjective, so そうな can modify nouns and そうに can modify verbs: 高そうな時計 = ''an expensive-looking watch''; 楽しそうに遊ぶ = ''play in a way that looks fun''.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'The appearance そう conjugates like a な-adjective, so そうな can modify nouns and そうに can modify verbs: 高そうな時計 = ''an expensive-looking watch''; 楽しそうに遊ぶ = ''play in a way that looks fun''.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Only appearance そう has these forms — hearsay そうだ never becomes そうな or そうに.
そうな goes before a noun, そうに before a verb: 楽しそうな人 / 楽しそうに話す.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Only appearance そう has these forms — hearsay そうだ never becomes そうな or そうに.
そうな goes before a noun, そうに before a verb: 楽しそうな人 / 楽しそうに話す.');
SET @Parents += @@ROWCOUNT;
