AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'sou-ni-sou-na:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'sou-ni-sou-na:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼は高そうな時計をしています。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼は高そうな時計をしています。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
