IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'それで' AND DATALENGTH(c.Pattern) = DATALENGTH(N'それで') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'それで' AND DATALENGTH(c.Reading) = DATALENGTH(N'それで') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Vì vậy, rồi sao nữa', Formation = N'Câu nêu tình huống ＋ それで ＋ câu nêu kết quả hoặc câu hỏi', Explanation = N'Nối nguyên nhân với kết quả hoặc hỏi diễn biến tiếp theo khi nghe kể chuyện.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'and so; because of that; so then?' AND DATALENGTH(c.Meaning) = DATALENGTH(N'and so; because of that; so then?') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence。 ＋ それで ＋ Sentence' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence。 ＋ それで ＋ Sentence') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'それで opens a sentence and links it to the previous one as its result: 熱があった。それで、休んだ = ''I had a fever. So I stayed home.'' In conversation a bare それで？ nudges the other person to continue the story: ''and then?''.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'それで opens a sentence and links it to the previous one as its result: 熱があった。それで、休んだ = ''I had a fever. So I stayed home.'' In conversation a bare それで？ nudges the other person to continue the story: ''and then?''.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'それで states a natural result; commands and invitations tend to follow だから instead — だから早く来てください rather than それで早く来てください.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'それで states a natural result; commands and invitations tend to follow だから instead — だから早く来てください rather than それで早く来てください.');
