IF @Matches > 1 THROW 51001, 'Ambiguous translation source: sore-demo', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'それでも' AND DATALENGTH(c.Pattern) = DATALENGTH(N'それでも') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'それでも' AND DATALENGTH(c.Reading) = DATALENGTH(N'それでも') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Dù vậy, thế mà vẫn', Formation = N'Câu trước ＋ それでも ＋ câu sau', Explanation = N'Nêu kết quả vẫn xảy ra dù hoàn cảnh trước đó khiến người nghe có thể kỳ vọng điều ngược lại.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'even so; nevertheless; despite that' AND DATALENGTH(c.Meaning) = DATALENGTH(N'even so; nevertheless; despite that') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence。 ＋ それでも ＋ Sentence。' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence。 ＋ それでも ＋ Sentence。') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'それでも opens a sentence to say that, granting everything just stated, the result still went the other way. It concedes the previous fact and then pushes against it: ''even given that, ~ anyway.'' Use it when an outcome defies what the earlier sentence would lead you to expect.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'それでも opens a sentence to say that, granting everything just stated, the result still went the other way. It concedes the previous fact and then pushes against it: ''even given that, ~ anyway.'' Use it when an outcome defies what the earlier sentence would lead you to expect.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'それでも concedes then contrasts (''even so''). Don''t mix it up with それで, which draws a natural result (''and so'') with no reversal.
It starts a fresh sentence. To link the two ideas inside one sentence, use 〜のに or 〜けど instead.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'それでも concedes then contrasts (''even so''). Don''t mix it up with それで, which draws a natural result (''and so'') with no reversal.
It starts a fresh sentence. To link the two ideas inside one sentence, use 〜のに or 〜けど instead.');
