IF @Matches > 1 THROW 51001, 'Ambiguous translation source: daga-desuga', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'だが・ですが' AND DATALENGTH(c.Pattern) = DATALENGTH(N'だが・ですが') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'だが・ですが' AND DATALENGTH(c.Reading) = DATALENGTH(N'だが・ですが') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Nhưng, tuy nhiên', Formation = N'Câu trước ＋ だが／ですが ＋ câu sau', Explanation = N'Nối hai ý tương phản. ですが lịch sự hơn だが.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'but; however' AND DATALENGTH(c.Meaning) = DATALENGTH(N'but; however') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence。 ＋ だが／ですが ＋ Sentence。' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence。 ＋ だが／ですが ＋ Sentence。') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'だが and ですが open a sentence with a contrast to what came before. だが is blunt and rather written or formal; ですが is its polite spoken counterpart, common for softening a disagreement. Both mean ''but / however'' at the start of a new sentence.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'だが and ですが open a sentence with a contrast to what came before. だが is blunt and rather written or formal; ですが is its polite spoken counterpart, common for softening a disagreement. Both mean ''but / however'' at the start of a new sentence.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'だが sounds formal or curt; in polite conversation prefer ですが, or the casual でも／けど.
These begin a new sentence. To join a contrast within one sentence, use 〜が or 〜けど.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'だが sounds formal or curt; in polite conversation prefer ですが, or the casual でも／けど.
These begin a new sentence. To join a contrast within one sentence, use 〜が or 〜けど.');
