IF @Matches > 1 THROW 51001, 'Ambiguous translation source: tagaru', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'たがる' AND DATALENGTH(c.Pattern) = DATALENGTH(N'たがる') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'たがる' AND DATALENGTH(c.Reading) = DATALENGTH(N'たがる') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Tỏ ra muốn làm gì', Formation = N'Gốc ます ＋ たがる／たがっている', Explanation = N'Dùng khi nhận xét mong muốn của người khác qua hành vi. たがっている thường nói mong muốn đang thể hiện.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to want to (of a third person, shown outwardly)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to want to (of a third person, shown outwardly)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ たがる' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ たがる') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'たがる reports that someone else looks like they want to do something, judged from outside signs. It''s built from the 〜たい stem plus がる, and conjugates like an u-verb. Use it for other people''s desires; for your own, plain 〜たい is correct.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'たがる reports that someone else looks like they want to do something, judged from outside signs. It''s built from the 〜たい stem plus がる, and conjugates like an u-verb. Use it for other people''s desires; for your own, plain 〜たい is correct.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Use たがる for others'' wants observed from outside; for your own desire say 〜たい (食べたい), not 食べたがる.
For a want happening right now, the ongoing 〜たがっている is usually more natural than plain 〜たがる.
たがる tends to take を for its object (お菓子を食べたがる), where 〜たい can also use が.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Use たがる for others'' wants observed from outside; for your own desire say 〜たい (食べたい), not 食べたがる.
For a want happening right now, the ongoing 〜たがっている is usually more natural than plain 〜たがる.
たがる tends to take を for its object (お菓子を食べたがる), where 〜たい can also use が.');
