BEGIN
UPDATE c SET Meaning = N'Chỉ cần, chỉ bằng', Formation = N'Động từ thể từ điển hoặc danh từ ＋ だけで', Explanation = N'Nêu một việc hoặc phương tiện đã đủ để có kết quả.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'just by; just with; just from' AND DATALENGTH(c.Meaning) = DATALENGTH(N'just by; just with; just from') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ だけで
Noun ＋ だけで' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ だけで
Noun ＋ だけで') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'だけで means ''merely by ~'' or ''with just ~.'' The で marks the small means or cause, and the sentence usually notes that this little is enough to bring some notable result. Attach it to a dictionary-form verb or a noun.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'だけで means ''merely by ~'' or ''with just ~.'' The で marks the small means or cause, and the sentence usually notes that this little is enough to bring some notable result. Attach it to a dictionary-form verb or a noun.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'だけで is ''just by/with,'' not just ''only'' — the で adds the sense of means or cause that plain だけ lacks.
