IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'他動詞・自動詞' AND DATALENGTH(c.Pattern) = DATALENGTH(N'他動詞・自動詞') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'たどうし・じどうし' AND DATALENGTH(c.Reading) = DATALENGTH(N'たどうし・じどうし') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Tha động từ và tự động từ', Formation = N'Chủ thể ＋ が／は ＋ tân ngữ ＋ を ＋ tha động từ／đối tượng ＋ が／は ＋ tự động từ', Explanation = N'Tha động từ như 消す nêu hành động tác động lên đối tượng. Tự động từ như 消える nêu sự thay đổi của chính đối tượng.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'transitive and intransitive verb pairs' AND DATALENGTH(c.Meaning) = DATALENGTH(N'transitive and intransitive verb pairs') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ を ＋ Verb［transitive］
Noun ＋ が ＋ Verb［intransitive］' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ を ＋ Verb［transitive］
Noun ＋ が ＋ Verb［intransitive］') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Japanese has many verb pairs: a 他動詞 (transitive), where someone acts on a thing marked with を, and a matching 自動詞 (intransitive), where the thing changes by itself and is marked with が. 開ける/開く, 閉める/閉まる, and 消す/消える are classic pairs you learn together.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Japanese has many verb pairs: a 他動詞 (transitive), where someone acts on a thing marked with を, and a matching 自動詞 (intransitive), where the thing changes by itself and is marked with が. 開ける/開く, 閉める/閉まる, and 消す/消える are classic pairs you learn together.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The transitive verb takes を and needs a doer; the intransitive takes が and describes the thing changing on its own.
The pairs must be memorized: 始める/始まる, 出す/出る, 入れる/入る don''t follow one fixed rule.
For a resulting state, use intransitive ＋ ている (ドアが開いている) or transitive ＋ てある (ドアが開けてある).' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The transitive verb takes を and needs a doer; the intransitive takes が and describes the thing changing on its own.
The pairs must be memorized: 始める/始まる, 出す/出る, 入れる/入る don''t follow one fixed rule.
For a resulting state, use intransitive ＋ ている (ドアが開いている) or transitive ＋ てある (ドアが開けてある).');
