FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'have just finished doing (this very moment)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'have just finished doing (this very moment)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［た form］＋ ところ（だ／です）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［た form］＋ ところ（だ／です）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Verb［た form］＋ ところ marks an action that finished a moment ago — you are right at the point just after it. It pins the event to the immediate present on a timeline, so it fits sentences like ''I just this second arrived.''' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Verb［た form］＋ ところ marks an action that finished a moment ago — you are right at the point just after it. It pins the event to the immediate present on a timeline, so it fits sentences like ''I just this second arrived.''') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'〜たところ is the moment just after finishing; 〜ているところ is the middle of doing, and 〜るところ is about to start.
