WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'tte-kanji' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'tte-kanji');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: tte-kanji', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'って感じ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'って感じ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ってかんじ' AND DATALENGTH(c.Reading) = DATALENGTH(N'ってかんじ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Có cảm giác là, kiểu như', Formation = N'Cụm từ hoặc câu ＋ って感じ', Explanation = N'Cách nói thân mật để diễn đạt ấn tượng hoặc tóm tắt cảm nhận.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'the vibe of ~; kind of like ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'the vibe of ~; kind of like ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun／Sentence［plain form］＋ って感じ（だ／がする）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun／Sentence［plain form］＋ って感じ（だ／がする）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'って感じ is casual speech for ''the feeling/vibe of ~.'' The って is the colloquial quoting particle and 感じ means ''impression,'' so together they wrap up a mood or a rough impression. It often trails off at the end of a thought or adds がする.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'って感じ is casual speech for ''the feeling/vibe of ~.'' The って is the colloquial quoting particle and 感じ means ''impression,'' so together they wrap up a mood or a rough impression. It often trails off at the end of a thought or adds がする.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It''s very casual — avoid it in polite speech or formal writing.
って here is the spoken quotative; 感じ is ''impression,'' so the whole thing gives a loose ''sort of like ~'' feel.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It''s very casual — avoid it in polite speech or formal writing.
って here is the spoken quotative; 感じ is ''impression,'' so the whole thing gives a loose ''sort of like ~'' feel.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Mệt quá, kiểu chẳng muốn làm gì nữa.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'tte-kanji:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'tte-kanji:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'もう疲れて、何もしたくないって感じ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'もう疲れて、何もしたくないって感じ。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Phim hôm nay tôi thấy cũng tạm được.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'tte-kanji:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'tte-kanji:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'今日の映画は、まあまあかなって感じだった。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'今日の映画は、まあまあかなって感じだった。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N4-G-019.json: te-de
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-de' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'te-de');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: te-de', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'て・で' AND DATALENGTH(c.Pattern) = DATALENGTH(N'て・で') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'て・で' AND DATALENGTH(c.Reading) = DATALENGTH(N'て・で') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Nối hành động hoặc nguyên nhân', Formation = N'Động từ thể て／で ＋ mệnh đề tiếp theo', Explanation = N'Có thể nối việc xảy ra theo thứ tự hoặc nêu điều dẫn đến cảm xúc hay kết quả ở vế sau.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'て-form linking clauses: and (then); because' AND DATALENGTH(c.Meaning) = DATALENGTH(N'て-form linking clauses: and (then); because') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ Sentence' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］＋ Sentence') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'The verb て-form links clauses together: it can list actions in order (''do A, and then B'') or give a light reason (''B because A''). The voiced で appears with certain verbs (読んで, 遊んで). The final verb carries the tense — the て-form itself stays tense-neutral.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'The verb て-form links clauses together: it can list actions in order (''do A, and then B'') or give a light reason (''B because A''). The voiced で appears with certain verbs (読んで, 遊んで). The final verb carries the tense — the て-form itself stays tense-neutral.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The て-form has no tense of its own; the last verb decides past or non-past for the whole sentence.
For a strong ''because,'' use から／ので; the て-cause fits best when the result is an emotion or natural outcome (聞いて驚いた).
Some verbs voice the ending to で: 読んで, 飲んで, 遊んで — never 読んて.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The て-form has no tense of its own; the last verb decides past or non-past for the whole sentence.
For a strong ''because,'' use から／ので; the て-cause fits best when the result is an emotion or natural outcome (聞いて驚いた).
Some verbs voice the ending to で: 読んで, 飲んで, 遊んで — never 読んて.');
SET @Parents += @@ROWCOUNT;
