AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-de:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'te-de:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'朝起きて、顔を洗った。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'朝起きて、顔を洗った。')
