AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-de:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'te-de:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'友だちからの手紙を読んで、うれしくなった。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'友だちからの手紙を読んで、うれしくなった。')
