AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-ageru' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'te-ageru');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: te-ageru', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'てあげる' AND DATALENGTH(c.Pattern) = DATALENGTH(N'てあげる') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'てあげる' AND DATALENGTH(c.Reading) = DATALENGTH(N'てあげる') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Làm gì giúp ai', Formation = N'Động từ thể て ＋ あげる', Explanation = N'Diễn tả hành động mang lợi ích cho người khác. Cân nhắc sắc thái ban ơn khi nói trực tiếp với người được giúp.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to do something (as a favor) for someone' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to do something (as a favor) for someone') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ あげる' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］＋ あげる') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ あげる does an action as a kindness for someone else, with the favor flowing away from the doer toward the receiver. It parallels あげる (''give''), but what''s handed over is an action rather than an object. Use it when you help someone out.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Verb［て form］＋ あげる does an action as a kindness for someone else, with the favor flowing away from the doer toward the receiver. It parallels あげる (''give''), but what''s handed over is an action rather than an object. Use it when you help someone out.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The favor goes outward, from the doer to someone else; a favor done toward you takes 〜てくれる.
Said straight to a superior it can sound condescending (''I''ll kindly do this for you''), so use it humbly or reword.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The favor goes outward, from the doer to someone else; a favor done toward you takes 〜てくれる.
Said straight to a superior it can sound condescending (''I''ll kindly do this for you''), so use it humbly or reword.');
SET @Parents += @@ROWCOUNT;
