IF @Matches > 1 THROW 51001, 'Ambiguous translation source: te-iku', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ていく' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ていく') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ていく' AND DATALENGTH(c.Reading) = DATALENGTH(N'ていく') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Tiếp tục từ nay, làm rồi đi', Formation = N'Động từ thể て ＋ いく', Explanation = N'Có thể nêu hành động tiếp diễn về sau hoặc một việc làm trước khi rời chỗ hiện tại.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to go on doing; to do and then go; to continue from now' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to go on doing; to do and then go; to continue from now') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ いく' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］＋ いく') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ いく carries an action or change away from the present into the future — ''keep on ~ing from here.'' It can also mean ''do something, then head off.'' Its mirror image is 〜てくる, which brings change up to now. Write the auxiliary いく in kana.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Verb［て form］＋ いく carries an action or change away from the present into the future — ''keep on ~ing from here.'' It can also mean ''do something, then head off.'' Its mirror image is 〜てくる, which brings change up to now. Write the auxiliary いく in kana.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'〜ていく moves change away into the future (増えていく); 〜てくる traces it up to the present.
When いく is the ''continue'' auxiliary, write it in kana (〜ていく) rather than as the full verb 行く.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'〜ていく moves change away into the future (増えていく); 〜てくる traces it up to the present.
When いく is the ''continue'' auxiliary, write it in kana (〜ていく) rather than as the full verb 行く.');
