AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-ita:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'te-ita:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'電話したとき、姉はテレビを見ていました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'電話したとき、姉はテレビを見ていました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Hồi nhỏ tôi sống ở Tokyo.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-ita:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'te-ita:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'子どものころ、東京に住んでいました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'子どものころ、東京に住んでいました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N4-G-020.json: te-itadakemasen-ka
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-itadakemasen-ka' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'te-itadakemasen-ka');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: te-itadakemasen-ka', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ていただけませんか' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ていただけませんか') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ていただけませんか' AND DATALENGTH(c.Reading) = DATALENGTH(N'ていただけませんか') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Có thể vui lòng làm giúp tôi không?', Formation = N'Động từ thể て ＋ いただけませんか', Explanation = N'Dạng yêu cầu trang trọng, hỏi người nghe có thể làm giúp một việc hay không.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'could you please ~? (very polite request)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'could you please ~? (very polite request)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ いただけませんか' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］＋ いただけませんか') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'A very polite, softened way to ask someone to do something for you. It is built on the humble いただく (to receive) in its negative-potential-question shape, literally ''couldn''t I receive the favor of your ~ing?'' — which lands as a respectful ''could you please ~?''. Reach for it with superiors, customers, and strangers.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'A very polite, softened way to ask someone to do something for you. It is built on the humble いただく (to receive) in its negative-potential-question shape, literally ''couldn''t I receive the favor of your ~ing?'' — which lands as a respectful ''could you please ~?''. Reach for it with superiors, customers, and strangers.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'This is softer and more polite than てください or てくれませんか; the affirmative ～ていただけますか is fine too but a touch more direct.
The subject is you (the one receiving the favor). てくださいませんか instead frames the other person as the doer; both are polite, but the viewpoint differs.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'This is softer and more polite than てください or てくれませんか; the affirmative ～ていただけますか is fine too but a touch more direct.
The subject is you (the one receiving the favor). てくださいませんか instead frames the other person as the doer; both are polite, but the viewpoint differs.');
SET @Parents += @@ROWCOUNT;
