IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ているところ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ているところ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ているところ' AND DATALENGTH(c.Reading) = DATALENGTH(N'ているところ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Đang đúng lúc làm gì', Formation = N'Động từ thể て ＋ いるところだ／いるところに', Explanation = N'Nhấn mạnh hành động đang diễn ra ngay lúc nói hoặc lúc sự việc khác xen vào.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'in the middle of doing; right now doing' AND DATALENGTH(c.Meaning) = DATALENGTH(N'in the middle of doing; right now doing') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ いるところ（だ／です）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］＋ いるところ（だ／です）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ところ literally means ''place'', but here it points to a stage in time. Verb＋ているところだ pins the action to exactly the stage of being in progress — ''I''m right in the middle of ~ing''. It is more pointed than plain ている, zooming in on this very moment.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ところ literally means ''place'', but here it points to a stage in time. Verb＋ているところだ pins the action to exactly the stage of being in progress — ''I''m right in the middle of ~ing''. It is more pointed than plain ている, zooming in on this very moment.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'There are three matching stages: 〜るところ (about to), 〜ているところ (in the middle), 〜たところ (just finished). Match the verb form to the stage you mean.
It describes a moment, so it pairs with 今 or ちょうど, not with a duration like 三時間.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'There are three matching stages: 〜るところ (about to), 〜ているところ (in the middle), 〜たところ (just finished). Match the verb form to the stage you mean.
It describes a moment, so it pairs with 今 or ちょうど, not with a duration like 三時間.');
SET @Parents += @@ROWCOUNT;
