IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ておく' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ておく') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ておく' AND DATALENGTH(c.Reading) = DATALENGTH(N'ておく') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Làm trước, chuẩn bị sẵn', Formation = N'Động từ thể て ＋ おく', Explanation = N'Thực hiện trước để phục vụ mục đích sau hoặc giữ trạng thái để dùng về sau.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to do in advance; to do (and leave it that way) on purpose' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to do in advance; to do (and leave it that way) on purpose') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［て form］＋ おく／おきます
Verb［て form］＋ とく［casual］' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［て form］＋ おく／おきます
Verb［て form］＋ とく［casual］') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'From 置く (to place), ておく means doing something ahead of time as preparation, or deliberately leaving something in a certain state. In casual speech it contracts: 〜ておく → 〜とく, 〜でおく → 〜どく.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'From 置く (to place), ておく means doing something ahead of time as preparation, or deliberately leaving something in a certain state. In casual speech it contracts: 〜ておく → 〜とく, 〜でおく → 〜どく.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Two senses share the form: preparing beforehand (予約しておく) and leaving something as-is on purpose (窓を開けておく).
The casual contraction drops いてお/んでお: 買っておく → 買っとく, 読んでおく → 読んどく.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Two senses share the form: preparing beforehand (予約しておく) and leaving something as-is on purpose (窓を開けておく).
The casual contraction drops いてお/んでお: 買っておく → 買っとく, 読んでおく → 読んどく.');
