AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'te-kuru:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'te-kuru:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'ちょっとパンを買ってきます。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'ちょっとパンを買ってきます。')
