BEGIN
UPDATE c SET Meaning = N'Làm gì giúp tôi hoặc phía tôi', Formation = N'Động từ thể て ＋ くれる', Explanation = N'Người thực hiện là chủ thể, còn người nói hoặc người thuộc phía người nói nhận lợi ích.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to do (a favor) for me/us' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to do (a favor) for me/us') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun［giver］＋ が ＋ Verb［て form］＋ くれる' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun［giver］＋ が ＋ Verb［て form］＋ くれる') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'てくれる marks that someone does an action as a favor for the speaker or the speaker''s in-group. The doer is the subject (が/は); the beneficiary is you, often left unstated. The direction of the favor points toward the speaker''s side.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'てくれる marks that someone does an action as a favor for the speaker or the speaker''s in-group. The doer is the subject (が/は); the beneficiary is you, often left unstated. The direction of the favor points toward the speaker''s side.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The direction is fixed toward the speaker: 友だちが手伝ってくれる (my friend helps me). If you do the favor for someone else, switch to てあげる.
Contrast てもらう: with てくれる the giver is the subject (友だちが〜くれた); with てもらう the receiver is (私が友だちに〜もらった). Same event, different viewpoint.
The honorific version is てくださる: 先生が教えてくださった.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The direction is fixed toward the speaker: 友だちが手伝ってくれる (my friend helps me). If you do the favor for someone else, switch to てあげる.
Contrast てもらう: with てくれる the giver is the subject (友だちが〜くれた); with てもらう the receiver is (私が友だちに〜もらった). Same event, different viewpoint.
The honorific version is てくださる: 先生が教えてくださった.');
