AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'to-quotation:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'to-quotation:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼は明日来ると言いました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼は明日来ると言いました。')
