-- N4-G-024.json: to-conditional
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'to-conditional' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'to-conditional');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: to-conditional', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'と' AND DATALENGTH(c.Pattern) = DATALENGTH(N'と') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'と' AND DATALENGTH(c.Reading) = DATALENGTH(N'と') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Hễ, cứ… thì', Formation = N'Mệnh đề thể thông thường ＋ と ＋ kết quả (danh từ và tính từ な dùng だ)', Explanation = N'Nêu kết quả tự nhiên, lặp lại hoặc điều được phát hiện khi làm theo hướng dẫn.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'whenever/if A, then B (natural result)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'whenever/if A, then B (natural result)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb／い-adjective［plain non-past］＋ と ＋ Sentence
Noun／な-adjective ＋ だと ＋ Sentence' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb／い-adjective［plain non-past］＋ と ＋ Sentence
Noun／な-adjective ＋ だと ＋ Sentence') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'と joins two clauses to say that whenever A happens, B follows automatically. It''s for predictable, natural consequences — how machines work, directions, habits, and cause-and-effect that always plays out the same way.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'と joins two clauses to say that whenever A happens, B follows automatically. It''s for predictable, natural consequences — how machines work, directions, habits, and cause-and-effect that always plays out the same way.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The B clause usually can''t be a request, invitation, or your own decision: avoid 〜と、〜てください. Use たら for those.
The part before と stays non-past plain, even about the past or the future: 春になると花が咲く.
This conditional と is separate from the quotative と (''that'') and the noun-linking と (''and'').' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The B clause usually can''t be a request, invitation, or your own decision: avoid 〜と、〜てください. Use たら for those.
The part before と stays non-past plain, even about the past or the future: 春になると花が咲く.
This conditional と is separate from the quotative と (''that'') and the noun-linking と (''and'').');
SET @Parents += @@ROWCOUNT;
