IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'と～と、どちらが' AND DATALENGTH(c.Pattern) = DATALENGTH(N'と～と、どちらが') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'と～とどちらが' AND DATALENGTH(c.Reading) = DATALENGTH(N'と～とどちらが') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Giữa A và B, bên nào?', Formation = N'A ＋ と ＋ B ＋ と、どちらが ＋ vị ngữ', Explanation = N'Hỏi lựa chọn hoặc so sánh giữa hai đối tượng.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'between A and B, which one?' AND DATALENGTH(c.Meaning) = DATALENGTH(N'between A and B, which one?') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun［A］＋ と ＋ Noun［B］＋ と、どちらが ＋ い-adjective／な-adjective ＋ か' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun［A］＋ と ＋ Noun［B］＋ と、どちらが ＋ い-adjective／な-adjective ＋ か') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'This pattern asks someone to compare exactly two things and choose: AとBと、どちらが〜？ = ''Between A and B, which is more ~?'' The reply typically comes back with 〜のほうが to name the winner.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'This pattern asks someone to compare exactly two things and choose: AとBと、どちらが〜？ = ''Between A and B, which is more ~?'' The reply typically comes back with 〜のほうが to name the winner.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Use どちら (casual どっち) for a choice between two items; for three or more, ask with どれ or use 一番.
The second と is often dropped: AとB、どちらが〜 is equally natural.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Use どちら (casual どっち) for a choice between two items; for three or more, ask with どれ or use 一番.
The second と is often dropped: AとB、どちらが〜 is equally natural.');
SET @Parents += @@ROWCOUNT;
