IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'という' AND DATALENGTH(c.Pattern) = DATALENGTH(N'という') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'という' AND DATALENGTH(c.Reading) = DATALENGTH(N'という') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Tên là, được gọi là', Formation = N'Tên hoặc tên gọi ＋ という ＋ danh từ', Explanation = N'Nêu tên của người, vật hoặc khái niệm trước danh từ được giới thiệu.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'called ~; named ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'called ~; named ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun［name］＋ という ＋ Noun
