UPDATE c SET Meaning = N'Giữ nguyên, cứ để vậy', Formation = N'Động từ thể た hoặc ない／danh từ ＋ の ＋ まま', Explanation = N'Trạng thái ban đầu vẫn tiếp tục khi việc khác diễn ra. Có thể thêm で sau まま.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'as it is; leaving/staying unchanged' AND DATALENGTH(c.Meaning) = DATALENGTH(N'as it is; leaving/staying unchanged') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［た form］＋ まま
