SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'mitai-na' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'mitai-na');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: mitai-na', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'みたいに・みたいな' AND DATALENGTH(c.Pattern) = DATALENGTH(N'みたいに・みたいな') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'みたいに・みたいな' AND DATALENGTH(c.Reading) = DATALENGTH(N'みたいに・みたいな') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Như, giống như (thân mật)', Formation = N'Danh từ ＋ みたいに ＋ vị ngữ／みたいな ＋ danh từ', Explanation = N'みたいに bổ nghĩa vị ngữ, còn みたいな bổ nghĩa danh từ.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'like ~; similar to ~ (resemblance/example)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'like ~; similar to ~ (resemblance/example)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ みたいな ＋ Noun
Noun ＋ みたいに ＋ Verb ／ Adjective' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ みたいな ＋ Noun
Noun ＋ みたいに ＋ Verb ／ Adjective') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'みたいな and みたいに express resemblance — ''like / similar to'' a given example. みたいな modifies a noun (夢みたいな話, a dream-like story), while みたいに modifies a verb or adjective (子どもみたいに笑う, laugh like a child). It''s the casual counterpart of ような・ように.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'みたいな and みたいに express resemblance — ''like / similar to'' a given example. みたいな modifies a noun (夢みたいな話, a dream-like story), while みたいに modifies a verb or adjective (子どもみたいに笑う, laugh like a child). It''s the casual counterpart of ような・ように.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'みたいな before a noun, みたいに before a verb or adjective — just like な vs に on な-adjectives.
This is the ''resemblance'' use; the same word ending a sentence as みたいだ instead makes a guess (''seems like'').' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'みたいな before a noun, みたいに before a verb or adjective — just like な vs に on な-adjectives.
This is the ''resemblance'' use; the same word ending a sentence as みたいだ instead makes a guess (''seems like'').');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Cô ấy hát hay như ca sĩ.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'mitai-na:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'mitai-na:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'彼女は歌手みたいに歌が上手だ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'彼女は歌手みたいに歌が上手だ。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Chuyện cứ như một giấc mơ nhỉ.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'mitai-na:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'mitai-na:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'夢みたいな話ですね。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'夢みたいな話ですね。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N4-G-034.json: meirei-kei
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'meirei-kei' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'meirei-kei');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: meirei-kei', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'命令形' AND DATALENGTH(c.Pattern) = DATALENGTH(N'命令形') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'めいれいけい' AND DATALENGTH(c.Reading) = DATALENGTH(N'めいれいけい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Thể mệnh lệnh', Formation = N'Nhóm 1: đổi âm cuối sang hàng え／nhóm 2: bỏ る ＋ ろ／する → しろ／来る → 来い', Explanation = N'Ra lệnh trực tiếp. Dạng này cũng dùng khi cổ vũ hoặc cảnh báo khẩn cấp.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'imperative form; blunt command ''do ~!''' AND DATALENGTH(c.Meaning) = DATALENGTH(N'imperative form; blunt command ''do ~!''') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb（godan）［ー u → e］（書く → 書け）
Verb（ichidan）［る → ろ］（見る → 見ろ）
する → しろ ／ 来る → 来い' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb（godan）［ー u → e］（書く → 書け）
Verb（ichidan）［る → ろ］（見る → 見ろ）
する → しろ ／ 来る → 来い') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'The 命令形 (imperative) is the plainest, most forceful way to order someone to do something — ''Do it!''. Godan verbs change their final -u to -e (書く → 書け, 待つ → 待て), ichidan verbs replace る with ろ (食べる → 食べろ), and the irregulars are しろ (する) and 来い (来る). It is strong and rough, used for orders, warnings, signs, and cheering.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'The 命令形 (imperative) is the plainest, most forceful way to order someone to do something — ''Do it!''. Godan verbs change their final -u to -e (書く → 書け, 待つ → 待て), ichidan verbs replace る with ろ (食べる → 食べろ), and the irregulars are しろ (する) and 来い (来る). It is strong and rough, used for orders, warnings, signs, and cheering.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The imperative is blunt and can sound harsh; for a polite request use 〜てください, built on the て form.
ください never attaches to the imperative: 食べろください is not Japanese — the polite form is 食べてください.
It shows up mostly in fixed contexts: sports cheers (頑張れ！), warning signs (止まれ), and quoting an order — not everyday polite conversation.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The imperative is blunt and can sound harsh; for a polite request use 〜てください, built on the て form.
ください never attaches to the imperative: 食べろください is not Japanese — the polite form is 食べてください.
It shows up mostly in fixed contexts: sports cheers (頑張れ！), warning signs (止まれ), and quoting an order — not everyday polite conversation.');
SET @Parents += @@ROWCOUNT;
