AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'meirei-kei:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'meirei-kei:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'頑張れ！あと少しだ。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'頑張れ！あと少しだ。')
