-- N4-G-035.json: moshi
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'moshi' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'moshi');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: moshi', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'もし' AND DATALENGTH(c.Pattern) = DATALENGTH(N'もし') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'もし' AND DATALENGTH(c.Reading) = DATALENGTH(N'もし') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Nếu, giả sử', Formation = N'もし ＋ mệnh đề điều kiện dạng たら／なら／ば', Explanation = N'Đặt giả thiết trước khi nêu kết quả, dự định hoặc lời đề nghị.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'if (flagging a hypothetical)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'if (flagging a hypothetical)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'もし ＋ Verb［た form］＋ ら
もし ＋ Sentence［with たら／ば／なら］' AND DATALENGTH(c.Formation) = DATALENGTH(N'もし ＋ Verb［た form］＋ ら
もし ＋ Sentence［with たら／ば／なら］') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'もし is an adverb that signals a supposition is coming. It does not form the conditional by itself — it pairs with a conditional ending like たら, ば, なら, or と, and simply announces early in the sentence that what follows is hypothetical. It often adds a ''just supposing'' feel.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'もし is an adverb that signals a supposition is coming. It does not form the conditional by itself — it pairs with a conditional ending like たら, ば, なら, or と, and simply announces early in the sentence that what follows is hypothetical. It often adds a ''just supposing'' feel.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'もし needs a conditional ending to finish the thought; it does not replace たら／ば／なら. Say もし雨が降ったら, not もし雨が降る.
もし flags a hypothesis. For a fact that always follows, drop もし and use a plain conditional or と.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'もし needs a conditional ending to finish the thought; it does not replace たら／ば／なら. Say もし雨が降ったら, not もし雨が降る.
もし flags a hypothesis. For a fact that always follows, drop もし and use a plain conditional or と.');
SET @Parents += @@ROWCOUNT;
