-- N4-G-035.json: you-da
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'you-da' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'you-da');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: you-da', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ようだ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ようだ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ようだ' AND DATALENGTH(c.Reading) = DATALENGTH(N'ようだ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Có vẻ, dường như', Formation = N'Mệnh đề bổ nghĩa ＋ ようだ (danh từ ＋ の／tính từ な ＋ な)', Explanation = N'Trình bày suy đoán dựa trên dấu hiệu hoặc tình huống quan sát được.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'it seems that; it appears (from evidence)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'it seems that; it appears (from evidence)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［plain form］＋ ようだ
い-adjective ＋ ようだ
な-adjective ＋ な ＋ ようだ
Noun ＋ の ＋ ようだ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［plain form］＋ ようだ
い-adjective ＋ ようだ
な-adjective ＋ な ＋ ようだ
Noun ＋ の ＋ ようだ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ようだ expresses a conjecture the speaker draws from what they can see, hear, or otherwise sense. It is a fairly objective ''it seems / it appears'', grounded in evidence rather than a wild guess. It attaches to plain forms; nouns take の and な-adjectives take な before よう.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ようだ expresses a conjecture the speaker draws from what they can see, hear, or otherwise sense. It is a fairly objective ''it seems / it appears'', grounded in evidence rather than a wild guess. It attaches to plain forms; nouns take の and な-adjectives take な before よう.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Nouns need の, not だ: 学生のようだ, not 学生だようだ.
ようだ rests on the speaker''s own observation. For something you only heard from someone else, use そうだ (hearsay) or らしい.
In casual speech みたい replaces ようだ with the same meaning: 雨が降ったみたい.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Nouns need の, not だ: 学生のようだ, not 学生だようだ.
ようだ rests on the speaker''s own observation. For something you only heard from someone else, use そうだ (hearsay) or らしい.
In casual speech みたい replaces ようだ with the same meaning: 雨が降ったみたい.');
