SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'you-to-omou' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'you-to-omou');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: you-to-omou', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ようと思う' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ようと思う') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ようとおもう' AND DATALENGTH(c.Reading) = DATALENGTH(N'ようとおもう') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Định làm gì', Formation = N'Động từ thể ý hướng ＋ と思う／と思っている', Explanation = N'Nêu dự định. と思っている có thể nói về ý định đã có từ trước.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'I think I''ll ~; I''m thinking of ~ing' AND DATALENGTH(c.Meaning) = DATALENGTH(N'I think I''ll ~; I''m thinking of ~ing') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［volitional］＋ と思う
食べようと思う ／ 行こうと思う' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［volitional］＋ と思う
食べようと思う ／ 行こうと思う') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Volitional verb ＋ と思う states a personal intention the speaker has more or less just formed. It is softer than declaring a fixed plan — it presents the decision as your current thinking. Use ようと思っている for an intention you have been holding for a while.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Volitional verb ＋ と思う states a personal intention the speaker has more or less just formed. It is softer than declaring a fixed plan — it presents the decision as your current thinking. Use ようと思っている for an intention you have been holding for a while.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Attach it to the volitional (行こう), not the dictionary form: 行こうと思う, not 行くと思う (which just means ''I think he''ll go'').
ようと思う reports the speaker''s own intention; you cannot use it to state someone else''s will directly.
と思っている suggests a longer-held intention; plain と思う, a decision made at the moment of speaking.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Attach it to the volitional (行こう), not the dictionary form: 行こうと思う, not 行くと思う (which just means ''I think he''ll go'').
ようと思う reports the speaker''s own intention; you cannot use it to state someone else''s will directly.
と思っている suggests a longer-held intention; plain と思う, a decision made at the moment of speaking.');
SET @Parents += @@ROWCOUNT;
