AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'you-to-omou:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'you-to-omou:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'週末は家でゆっくりしようと思います。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'週末は家でゆっくりしようと思います。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
