AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'you-to-omou:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'you-to-omou:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'来年、日本語の試験を受けようと思っています。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'来年、日本語の試験を受けようと思っています。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N4-G-035.json: you-ni-so-that
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'you-ni-so-that' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'you-ni-so-that');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: you-ni-so-that', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ように' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ように') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ように' AND DATALENGTH(c.Reading) = DATALENGTH(N'ように') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Để, sao cho', Formation = N'Động từ thể từ điển hoặc thể ない ＋ ように', Explanation = N'Nêu kết quả hoặc trạng thái muốn đạt hay tránh. Thường dùng với thể khả năng hoặc hành động khó kiểm soát trực tiếp.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'so that; in order to (a state comes about)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'so that; in order to (a state comes about)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ ように
Verb［ない form］＋ ように
Verb［potential form］＋ ように' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ ように
Verb［ない form］＋ ように
Verb［potential form］＋ ように') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ように states the purpose behind an action — you do the main action so that some situation will come about. The clause before ように is usually a state or a potential / negative verb (something you cannot directly will), like 聞こえる, わかる, or 忘れない. It contrasts with ために, whose front clause is a deliberate action.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ように states the purpose behind an action — you do the main action so that some situation will come about. The clause before ように is usually a state or a potential / negative verb (something you cannot directly will), like 聞こえる, わかる, or 忘れない. It contrasts with ために, whose front clause is a deliberate action.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'ように takes a non-volitional verb (potential, negative, or change of state): 見えるように. For a goal reached by deliberate action, use ために: 車を買うために.
No の or な before this ように — it attaches straight to the plain verb.
The two clauses can have different subjects, which suits ように but is awkward for ために.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'ように takes a non-volitional verb (potential, negative, or change of state): 見えるように. For a goal reached by deliberate action, use ために: 車を買うために.
No の or な before this ように — it attaches straight to the plain verb.
The two clauses can have different subjects, which suits ように but is awkward for ために.');
SET @Parents += @@ROWCOUNT;
