-- N4-G-035.json: you-ni-you-na
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'you-ni-you-na' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'you-ni-you-na');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: you-ni-you-na', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ように・ような' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ように・ような') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ように・ような' AND DATALENGTH(c.Reading) = DATALENGTH(N'ように・ような') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Như, giống như', Formation = N'Danh từ ＋ のように ＋ vị ngữ／のような ＋ danh từ', Explanation = N'Dùng một hình ảnh để so sánh. ように bổ nghĩa vị ngữ, ような bổ nghĩa danh từ.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'like; similar to; as if' AND DATALENGTH(c.Meaning) = DATALENGTH(N'like; similar to; as if') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ の ＋ ような ＋ Noun
Noun ＋ の ＋ ように ＋ Verb／Adjective
Verb［plain form］＋ ように／ような' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ の ＋ ような ＋ Noun
Noun ＋ の ＋ ように ＋ Verb／Adjective
Verb［plain form］＋ ように／ような') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'This よう compares one thing to another: ような modifies a noun (''a ~ like X''), ように modifies a verb or adjective (''in a ~ way, like X''). It draws a resemblance or gives an example. Nouns connect with の: 夢のような (''dream-like'').' AND DATALENGTH(c.Explanation) = DATALENGTH(N'This よう compares one thing to another: ような modifies a noun (''a ~ like X''), ように modifies a verb or adjective (''in a ~ way, like X''). It draws a resemblance or gives an example. Nouns connect with の: 夢のような (''dream-like'').') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'ような goes before a noun, ように before a verb or adjective: 子どものような笑顔 vs 子どものように笑う.
Nouns need の: 山のように, not 山ように.
This is the ''resemblance'' よう; the same shape also builds ようだ (''it seems'') — context tells them apart.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'ような goes before a noun, ように before a verb or adjective: 子どものような笑顔 vs 子どものように笑う.
Nouns need の: 山のように, not 山ように.
This is the ''resemblance'' よう; the same shape also builds ようだ (''it seems'') — context tells them apart.');
SET @Parents += @@ROWCOUNT;
