AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'you-ni-te-hoshii' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'you-ni-te-hoshii');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: you-ni-te-hoshii', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ように～てほしい' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ように～てほしい') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ように～てほしい' AND DATALENGTH(c.Reading) = DATALENGTH(N'ように～てほしい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Muốn ai làm gì để đạt một kết quả', Formation = N'Động từ thể từ điển hoặc ない ＋ ように、động từ thể て ＋ ほしい', Explanation = N'Vế ように nêu mục đích, còn てほしい nêu hành động muốn người khác thực hiện.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'want someone to act so that ~ comes about' AND DATALENGTH(c.Meaning) = DATALENGTH(N'want someone to act so that ~ comes about') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］／Verb［ない form］＋ ように ＋ Verb［て form］＋ ほしい' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］／Verb［ない form］＋ ように ＋ Verb［て form］＋ ほしい') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'This pattern layers a ように purpose clause onto a てほしい request: you name the outcome you are hoping for with ように, then say you want someone to act toward it with 〜てほしい. It makes the wish gentle and outcome-focused — you care about the result, not just the bare action.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'This pattern layers a ように purpose clause onto a てほしい request: you name the outcome you are hoping for with ように, then say you want someone to act toward it with 〜てほしい. It makes the wish gentle and outcome-focused — you care about the result, not just the bare action.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The ように clause usually takes a non-volitional verb (potential, negative, or change of state): 遅れないように, 間に合うように.
てほしい voices a want directed at another person; you cannot use it for your own actions.
The negative want is 〜ないでほしい: 心配しないでほしい (''I don''t want you to worry'').' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The ように clause usually takes a non-volitional verb (potential, negative, or change of state): 遅れないように, 間に合うように.
てほしい voices a want directed at another person; you cannot use it for your own actions.
The negative want is 〜ないでほしい: 心配しないでほしい (''I don''t want you to worry'').');
