WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'yori' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'yori');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: yori', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'より' AND DATALENGTH(c.Pattern) = DATALENGTH(N'より') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'より' AND DATALENGTH(c.Reading) = DATALENGTH(N'より') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Hơn, so với', Formation = N'Mốc so sánh ＋ より', Explanation = N'より đánh dấu mốc để so sánh. ほうが có thể đánh dấu phía nổi trội.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'than; compared to' AND DATALENGTH(c.Meaning) = DATALENGTH(N'than; compared to') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ より ＋ い-adjective／な-adjective
A ＋ は ＋ B ＋ より ＋ adjective' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ より ＋ い-adjective／な-adjective
A ＋ は ＋ B ＋ より ＋ adjective') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'より marks the standard you compare against — the ''than X'' in a comparison. It attaches right after the noun used as the yardstick: 去年より暑い = ''hotter than last year''. The thing that comes out higher is usually marked with は or のほうが.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'より marks the standard you compare against — the ''than X'' in a comparison. It attaches right after the noun used as the yardstick: 去年より暑い = ''hotter than last year''. The thing that comes out higher is usually marked with は or のほうが.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'より comes right after the standard being beaten: 電車は車より速い, so 車より sits next to 速い.
To pick the top out of three or more, use 一番, not より (which compares two things).
This より (comparison) is different from the formal より meaning ''from''.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'より comes right after the standard being beaten: 電車は車より速い, so 車より sits next to 速い.
To pick the top out of three or more, use 一番, not より (which compares two things).
This より (comparison) is different from the formal より meaning ''from''.');
SET @Parents += @@ROWCOUNT;
