IF @Matches > 1 THROW 51001, 'Ambiguous translation source: rashii', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'らしい' AND DATALENGTH(c.Pattern) = DATALENGTH(N'らしい') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'らしい' AND DATALENGTH(c.Reading) = DATALENGTH(N'らしい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Nghe nói, có vẻ như', Formation = N'Thể thông thường ＋ らしい (danh từ và tính từ な bỏ だ)', Explanation = N'Trình bày thông tin gián tiếp hoặc suy đoán từ thông tin có được.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'apparently; it seems; I hear that' AND DATALENGTH(c.Meaning) = DATALENGTH(N'apparently; it seems; I hear that') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［plain form］＋ らしい
い-adjective ＋ らしい
な-adjective ＋ らしい
Noun ＋ らしい' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［plain form］＋ らしい
い-adjective ＋ らしい
な-adjective ＋ らしい
Noun ＋ らしい') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'らしい reports a conclusion the speaker draws from information that came from outside — something heard, read, or otherwise gathered. It is less about the speaker''s own eyes and more ''from what I gather''. It attaches to plain forms; with nouns and な-adjectives it joins bare, with no の or な.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'らしい reports a conclusion the speaker draws from information that came from outside — something heard, read, or otherwise gathered. It is less about the speaker''s own eyes and more ''from what I gather''. It attaches to plain forms; with nouns and な-adjectives it joins bare, with no の or な.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Nouns and な-adjectives attach bare — 学生らしい, 元気らしい — with no の or な, unlike ようだ (学生のようだ).
らしい leans on secondhand or gathered information; for a guess from what you directly see, ようだ fits better.
This hearsay らしい is a separate point from the らしい meaning ''typical of'' (男らしい ''manly'').' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Nouns and な-adjectives attach bare — 学生らしい, 元気らしい — with no の or な, unlike ようだ (学生のようだ).
らしい leans on secondhand or gathered information; for a guess from what you directly see, ようだ fits better.
This hearsay らしい is a separate point from the らしい meaning ''typical of'' (男らしい ''manly'').');
