WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'20044dd689' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'20044dd689');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: 20044dd689', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'医学' AND DATALENGTH(c.Word) = DATALENGTH(N'医学') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'いがく' AND DATALENGTH(c.Reading) = DATALENGTH(N'いがく') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
BEGIN
UPDATE c SET Meaning = N'Y học', PartOfSpeech = N'Danh từ', Explanation = N'医学（いがく）là ngành y học. 医学を学ぶ nghĩa là học y.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'medical science' AND DATALENGTH(c.Meaning) = DATALENGTH(N'medical science') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'n' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'n') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
