AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'123119' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'123119') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'二人の医者が医学の話をしていた。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'二人の医者が医学の話をしていた。')
