IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'都合' AND DATALENGTH(c.Word) = DATALENGTH(N'都合') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'つごう' AND DATALENGTH(c.Reading) = DATALENGTH(N'つごう') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N4' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N4'))
