FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'circumstances; convenience' AND DATALENGTH(c.Meaning) = DATALENGTH(N'circumstances; convenience') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'n' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'n') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
