FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'always; usually' AND DATALENGTH(c.Meaning) = DATALENGTH(N'always; usually') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'いつも ＋ Verb／Sentence' AND DATALENGTH(c.Formation) = DATALENGTH(N'いつも ＋ Verb／Sentence') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'いつも is an adverb meaning ''always'' or ''usually'' — it says an action or state holds all or most of the time. It normally comes before the verb it describes: いつも早く起きます = I always get up early. It describes a habit, not one particular occasion.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'いつも is an adverb meaning ''always'' or ''usually'' — it says an action or state holds all or most of the time. It normally comes before the verb it describes: いつも早く起きます = I always get up early. It describes a habit, not one particular occasion.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'いつも describes a habit. For a one-time ''this time'', use 今日 or 今度 instead.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'いつも describes a habit. For a one-time ''this time'', use 今日 or 今度 instead.');
