BEGIN
UPDATE c SET Meaning = N'Sau khi làm xong A thì làm B', Formation = N'Động từ A thể て ＋ から ＋ mệnh đề B', Explanation = N'〜てから cho biết việc B xảy ra sau khi việc A đã diễn ra hoặc hoàn tất. Mẫu này nhấn mạnh thứ tự.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
