FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'very; extremely' AND DATALENGTH(c.Meaning) = DATALENGTH(N'very; extremely') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'とても ＋ い-adjective ／ な-adjective' AND DATALENGTH(c.Formation) = DATALENGTH(N'とても ＋ い-adjective ／ な-adjective') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Intensifies an adjective or adverb: put とても before it to say ''very''. It is a neutral, everyday booster that works in both polite and casual speech, and it is one of the first intensifiers a learner uses.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Intensifies an adjective or adverb: put とても before it to say ''very''. It is a neutral, everyday booster that works in both polite and casual speech, and it is one of the first intensifiers a learner uses.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Place it before the word it strengthens, never after — とても おいしい, not おいしい とても.
With a negative verb, とても can mean ''cannot possibly'', but the plain ''very'' use is by far the most common at this level.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Place it before the word it strengthens, never after — とても おいしい, not おいしい とても.
With a negative verb, とても can mean ''cannot possibly'', but the plain ''very'' use is by far the most common at this level.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Món này rất ngon.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'totemo:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'totemo:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'この料理はとてもおいしいです。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'この料理はとてもおいしいです。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
