AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'totemo:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'totemo:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'昨日はとても寒かったです。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'昨日はとても寒かったです。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
