-- N5-G-013.json: donna
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'donna' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'donna');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: donna', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'どんな' AND DATALENGTH(c.Pattern) = DATALENGTH(N'どんな') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'どんな' AND DATALENGTH(c.Reading) = DATALENGTH(N'どんな') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Loại nào, như thế nào', Formation = N'どんな ＋ danh từ', Explanation = N'どんな đứng trước danh từ để hỏi loại hoặc đặc điểm. どんな音楽 hỏi thể loại nhạc, còn どんな人 hỏi người đó như thế nào.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'what kind of ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'what kind of ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'どんな ＋ Noun' AND DATALENGTH(c.Formation) = DATALENGTH(N'どんな ＋ Noun') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Asks about the type or nature of something: put どんな before a noun to ask ''what kind of ~?''. It requests a description of qualities rather than a specific name, so answers describe what the thing is like.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Asks about the type or nature of something: put どんな before a noun to ask ''what kind of ~?''. It requests a description of qualities rather than a specific name, so answers describe what the thing is like.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'どんな is always followed by a noun; it cannot stand alone the way ''what'' can.
To ask which specific one out of a known set, use どの instead of どんな.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'どんな is always followed by a noun; it cannot stand alone the way ''what'' can.
To ask which specific one out of a known set, use どの instead of どんな.');
SET @Parents += @@ROWCOUNT;
