AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'donna:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'donna:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'どんな音楽が好きですか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'どんな音楽が好きですか。')
