AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'donna:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'donna:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'あの人はどんな人ですか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'あの人はどんな人ですか。')
