-- N5-G-013.json: na-prohibitive
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'na-prohibitive' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'na-prohibitive');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: na-prohibitive', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'な' AND DATALENGTH(c.Pattern) = DATALENGTH(N'な') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'な' AND DATALENGTH(c.Reading) = DATALENGTH(N'な') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Cấm làm, đừng làm', Formation = N'Động từ dạng từ điển ＋ な', Explanation = N'Thêm な vào sau động từ dạng từ điển để cấm làm việc gì. Cách nói trực tiếp và mạnh, thường gặp trong mệnh lệnh hoặc lời cảnh báo.', UsageNotes = N'ないでください phù hợp hơn khi cần yêu cầu lịch sự.', UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'don''t ~ (blunt prohibition)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'don''t ~ (blunt prohibition)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ な' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ な') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Forbids an action bluntly: attach な to the dictionary form of a verb to say ''don''t do that''. It is strong, direct, and rather rough, heard in commands, warnings, and emphatic speech, mostly among men or in urgent situations.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Forbids an action bluntly: attach な to the dictionary form of a verb to say ''don''t do that''. It is strong, direct, and rather rough, heard in commands, warnings, and emphatic speech, mostly among men or in urgent situations.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'This is harsh and can sound rude — for everyday polite prohibition, use 〜ないでください instead.
Do not confuse it with the sentence-softening な or the な that links な-adjectives; the prohibitive attaches to a dictionary-form verb.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'This is harsh and can sound rude — for everyday polite prohibition, use 〜ないでください instead.
Do not confuse it with the sentence-softening な or the な that links な-adjectives; the prohibitive attaches to a dictionary-form verb.');
SET @Parents += @@ROWCOUNT;
