-- N5-G-013.json: naa
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'naa' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'naa');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: naa', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'なあ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'なあ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'なあ' AND DATALENGTH(c.Reading) = DATALENGTH(N'なあ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Nhỉ, quá (bộc lộ cảm xúc)', Formation = N'Câu thể thông thường ＋ なあ', Explanation = N'なあ đứng cuối câu để bộc lộ cảm xúc, sự ngạc nhiên hoặc cảm thán. Người nói có thể đang tự nhủ.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'sentence-ending particle: feeling, admiration' AND DATALENGTH(c.Meaning) = DATALENGTH(N'sentence-ending particle: feeling, admiration') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence［plain form］＋ なあ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence［plain form］＋ なあ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Adds emotional color at the end of a sentence: なあ voices admiration, strong feeling, or musing to oneself, often a drawn-out, more emotional version of ね. It is casual and typical of talking to yourself or chatting with close friends.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Adds emotional color at the end of a sentence: なあ voices admiration, strong feeling, or musing to oneself, often a drawn-out, more emotional version of ね. It is casual and typical of talking to yourself or chatting with close friends.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'It is casual — avoid it in polite ですます speech with people you don''t know well.
Unlike ね, which seeks the listener''s agreement, なあ often just voices your own feeling out loud.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'It is casual — avoid it in polite ですます speech with people you don''t know well.
Unlike ね, which seeks the listener''s agreement, なあ often just voices your own feeling out loud.');
SET @Parents += @@ROWCOUNT;
