-- N5-G-013.json: naide
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'naide' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'naide');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: naide', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ないで' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ないで') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ないで' AND DATALENGTH(c.Reading) = DATALENGTH(N'ないで') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Làm B mà không làm A', Formation = N'Động từ A thể ない ＋ で ＋ động từ B', Explanation = N'Dùng 〜ないで để nói việc B diễn ra mà không thực hiện A. 食べないで行く nghĩa là đi mà không ăn.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'without doing ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'without doing ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［ない form］＋ で ＋ Verb-B' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［ない form］＋ で ＋ Verb-B') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Links two actions where the first one does not happen: attach で to the ない form of a verb to say "do B without doing A". The clause before ないで names the action that is skipped, and the verb after it carries the sentence. Reach for it when you want to describe doing one thing while leaving another undone.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Links two actions where the first one does not happen: attach で to the ない form of a verb to say "do B without doing A". The clause before ないで names the action that is skipped, and the verb after it carries the sentence. Reach for it when you want to describe doing one thing while leaving another undone.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Don''t confuse ないで with なくて — both are negative connectors, but ないで attaches an accompanying non-action to the main verb, while なくて usually gives a cause or reason.
ないで attaches only to verbs — nouns and な-adjectives have no direct equivalent; ではなく expresses a different contrast (''not X, but Y''), not ''without doing''.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Don''t confuse ないで with なくて — both are negative connectors, but ないで attaches an accompanying non-action to the main verb, while なくて usually gives a cause or reason.
ないで attaches only to verbs — nouns and な-adjectives have no direct equivalent; ではなく expresses a different contrast (''not X, but Y''), not ''without doing''.');
SET @Parents += @@ROWCOUNT;
