AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'naide:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'naide:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'朝ご飯を食べないで学校に行きました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'朝ご飯を食べないで学校に行きました。')
