IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ないでください' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ないでください') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ないでください' AND DATALENGTH(c.Reading) = DATALENGTH(N'ないでください') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Xin đừng làm gì', Formation = N'Động từ thể ない ＋ でください', Explanation = N'Mẫu này dùng để lịch sự yêu cầu người nghe không làm một việc. 撮らないでください nghĩa là xin đừng chụp.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'please don''t do ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'please don''t do ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［ない form］＋ で ＋ ください' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［ない form］＋ で ＋ ください') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Politely asks someone not to do something: attach でください to the ない form of a verb. It is the negative partner of てください, so it is what you use to stop or warn someone gently in everyday polite speech.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Politely asks someone not to do something: attach でください to the ない form of a verb. It is the negative partner of てください, so it is what you use to stop or warn someone gently in everyday polite speech.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The verb goes into the plain ない form before で — 入らないでください, never 入りませんでください.
Dropping ください leaves plain ないで, which is a casual version fine among friends but too blunt in polite situations.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The verb goes into the plain ない form before で — 入らないでください, never 入りませんでください.
Dropping ください leaves plain ないで, which is a casual version fine among friends but too blunt in polite situations.');
