AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'naito-ikenai' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'naito-ikenai');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: naito-ikenai', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ないといけない' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ないといけない') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ないといけない' AND DATALENGTH(c.Reading) = DATALENGTH(N'ないといけない') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Phải làm gì', Formation = N'Động từ thể ない ＋ といけない／といけません', Explanation = N'Mẫu này diễn tả nghĩa vụ hoặc việc cần làm. Có thể hiểu là nếu không làm thì không được, nên phải làm.', UsageNotes = N'いけません là dạng lịch sự.', UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'must do; have to do ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'must do; have to do ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［ない form］＋ と ＋ いけない' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［ない form］＋ と ＋ いけない') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'States an obligation: attach といけない to the ない form of a verb to say "if you don''t do it, it won''t do", i.e. "you have to do it". It literally sets up a negative condition (ないと) and says that outcome is no good (いけない), which together mean the action is necessary.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'States an obligation: attach といけない to the ない form of a verb to say "if you don''t do it, it won''t do", i.e. "you have to do it". It literally sets up a negative condition (ないと) and says that outcome is no good (いけない), which together mean the action is necessary.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'The と here is the conditional ''if'', so the verb before it must be in the plain ない form.
In casual speech the いけない half is often dropped, leaving just ～ないと ("I''ve gotta...").' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'The と here is the conditional ''if'', so the verb before it must be in the plain ない form.
In casual speech the いけない half is often dropped, leaving just ～ないと ("I''ve gotta...").');
SET @Parents += @@ROWCOUNT;
