BEGIN
UPDATE c SET Meaning = N'Phải làm, cần làm (thân mật)', Formation = N'Động từ thể ない: đổi ない thành なくちゃ hoặc なきゃ', Explanation = N'なくちゃ rút gọn từ なくては, còn なきゃ rút gọn từ なければ. Trong hội thoại, phần diễn tả nghĩa vụ ở sau thường được lược mà câu vẫn mang nghĩa phải làm.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'gotta do; must do (casual)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'gotta do; must do (casual)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［ない → なくては］→ なくちゃ
Verb［ない → なければ］→ なきゃ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［ない → なくては］→ なくちゃ
