FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'na-adjective modifying a noun (~な＋noun)' AND DATALENGTH(c.Meaning) = DATALENGTH(N'na-adjective modifying a noun (~な＋noun)') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'な-adjective ＋ な ＋ Noun' AND DATALENGTH(c.Formation) = DATALENGTH(N'な-adjective ＋ な ＋ Noun') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Puts a な-adjective in front of a noun to describe it: insert な between the adjective and the noun. This な is exactly what gives these adjectives their name, and it appears only in this attributive position.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Puts a な-adjective in front of a noun to describe it: insert な between the adjective and the noun. This な is exactly what gives these adjectives their name, and it appears only in this attributive position.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'You must insert な — 静かな部屋, never 静か部屋.
い-adjectives don''t take な; they attach straight to the noun (静かな部屋 but 高い部屋).' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'You must insert な — 静かな部屋, never 静か部屋.
い-adjectives don''t take な; they attach straight to the noun (静かな部屋 but 高い部屋).');
