BEGIN
UPDATE c SET Meaning = N'Cái gì đó, không gì cả', Formation = N'何か／何も ＋ vị ngữ phủ định (với 何も)', Explanation = N'何か chỉ thứ chưa xác định. 何も đi với phủ định để nói không có hoặc không làm gì cả.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'something / not anything' AND DATALENGTH(c.Meaning) = DATALENGTH(N'something / not anything') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'何 ＋ か
