IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'のが好き' AND DATALENGTH(c.Pattern) = DATALENGTH(N'のが好き') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'のがすき' AND DATALENGTH(c.Reading) = DATALENGTH(N'のがすき') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Thích làm gì', Formation = N'Động từ dạng từ điển ＋ のが好き（です）', Explanation = N'のが好き dùng để nêu một hoạt động mình thích. の đứng sau động từ để danh từ hóa hoạt động đó.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'like doing ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'like doing ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ のが ＋ 好き（です）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ のが ＋ 好き（です）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'To say you like doing an activity, nominalize the verb with の, mark it with が, and add 好き. It expresses an ongoing preference or hobby rather than a one-time wish.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'To say you like doing an activity, nominalize the verb with の, mark it with が, and add 好き. It expresses an ongoing preference or hobby rather than a one-time wish.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'好き is a な-adjective and takes が, not を, right before it: 本を読むのが好き is correct, not 本を読むのを好き.
This describes a general liking; for a specific "I want to do it now" feeling use the たい form instead.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'好き is a な-adjective and takes が, not を, right before it: 本を読むのが好き is correct, not 本を読むのを好き.
This describes a general liking; for a specific "I want to do it now" feeling use the たい form instead.');
