BEGIN
UPDATE c SET Meaning = N'Không giỏi làm gì', Formation = N'Động từ dạng từ điển ＋ のが下手（です）', Explanation = N'下手 nhận xét một kỹ năng còn kém. の biến hành động thành cụm danh từ để nêu kỹ năng được nhận xét.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'bad at doing ~' AND DATALENGTH(c.Meaning) = DATALENGTH(N'bad at doing ~') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［dictionary form］＋ のが ＋ 下手（です）' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［dictionary form］＋ のが ＋ 下手（です）') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'To say someone is poor at an activity, nominalize the verb with の, mark it with が, and finish with 下手. Speakers often use it about themselves as a modest admission.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'To say someone is poor at an activity, nominalize the verb with の, mark it with が, and finish with 下手. Speakers often use it about themselves as a modest admission.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'下手 is a な-adjective and takes が, not を, right before it: 泳ぐのが下手 is correct, not 泳ぐのを下手.
