IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ので' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ので') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ので' AND DATALENGTH(c.Reading) = DATALENGTH(N'ので') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Vì, bởi vì', Formation = N'Động từ hoặc tính từ đuôi い thể thông thường ＋ ので
Danh từ hoặc gốc tính từ đuôi な ＋ なので', Explanation = N'ので nối lý do với kết quả hoặc quyết định. Mẫu này thường dùng để trình bày lý do nhẹ nhàng.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'because; since' AND DATALENGTH(c.Meaning) = DATALENGTH(N'because; since') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb／い-adjective［plain form］＋ ので
な-adjective／Noun ＋ な ＋ ので' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb／い-adjective［plain form］＋ ので
な-adjective／Noun ＋ な ＋ ので') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'ので connects a reason to its result, joining the cause clause to the main clause. Compared with から it feels softer and more matter-of-fact, so it is common in polite explanations, excuses, and requests.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'ので connects a reason to its result, joining the cause clause to the main clause. Compared with から it feels softer and more matter-of-fact, so it is common in polite explanations, excuses, and requests.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'After a な-adjective or a noun, add な before ので: 静かなので, 学生なので.
