FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'shall I ~?; shall we ~?' AND DATALENGTH(c.Meaning) = DATALENGTH(N'shall I ~?; shall we ~?') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ ましょうか' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ ましょうか') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Adds か to ましょう to turn a suggestion into a question. With one doer it offers help ("shall I ~?"); with a shared doer it proposes a joint action and checks whether the listener agrees ("shall we ~?"). Unlike plain ましょう, it asks rather than assumes.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Adds か to ましょう to turn a suggestion into a question. With one doer it offers help ("shall I ~?"); with a shared doer it proposes a joint action and checks whether the listener agrees ("shall we ~?"). Unlike plain ましょう, it asks rather than assumes.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'One subject means offering to do something for someone (手伝いましょうか = shall I help?); a shared subject means proposing to do it together.
It is more tentative than ましょう because it invites a yes-or-no answer.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'One subject means offering to do something for someone (手伝いましょうか = shall I help?); a shared subject means proposing to do it together.
It is more tentative than ましょう because it invites a yes-or-no answer.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Để tôi xách hành lý giúp nhé?'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'mashou-ka:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'mashou-ka:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'荷物を持ちましょうか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'荷物を持ちましょうか。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Mình về thôi nhỉ?'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'mashou-ka:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'mashou-ka:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'そろそろ帰りましょうか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'そろそろ帰りましょうか。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N5-G-021.json: masu
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'masu' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'masu');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: masu', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ます' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ます') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ます' AND DATALENGTH(c.Reading) = DATALENGTH(N'ます') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Đuôi động từ lịch sự', Formation = N'Động từ bỏ ます ＋ ます／ません／ました／ませんでした', Explanation = N'Các đuôi này lần lượt biểu thị khẳng định phi quá khứ, phủ định phi quá khứ, khẳng định quá khứ và phủ định quá khứ ở thể lịch sự.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'polite verb ending' AND DATALENGTH(c.Meaning) = DATALENGTH(N'polite verb ending') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ ます
Verb［stem］＋ ません ／ ました ／ ませんでした' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ ます
Verb［stem］＋ ません ／ ました ／ ませんでした') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Marks a verb as polite (the ます form), used in everyday conversation with people you are not close to, in public, and at work. It attaches to the verb stem and carries the tense: negative ません, past ました, negative-past ませんでした.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Marks a verb as polite (the ます form), used in everyday conversation with people you are not close to, in public, and at work. It attaches to the verb stem and carries the tense: negative ません, past ました, negative-past ませんでした.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'ます attaches to the stem, not the dictionary form — 飲む becomes 飲みます, never 飲むます.
The plain (dictionary) form is used with friends and family; switching registers mid-conversation can sound off.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'ます attaches to the stem, not the dictionary form — 飲む becomes 飲みます, never 飲むます.
The plain (dictionary) form is used with friends and family; switching registers mid-conversation can sound off.');
SET @Parents += @@ROWCOUNT;
