WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'masu:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'masu:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'毎朝コーヒーを飲みます。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'毎朝コーヒーを飲みます。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Hôm qua tôi không đi học.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'masu:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'masu:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'昨日は学校に行きませんでした。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'昨日は学校に行きませんでした。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
