-- N5-G-021.json: masen-ka
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'masen-ka' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'masen-ka');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: masen-ka', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'ませんか' AND DATALENGTH(c.Pattern) = DATALENGTH(N'ませんか') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ませんか' AND DATALENGTH(c.Reading) = DATALENGTH(N'ませんか') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Anh/chị có muốn cùng làm không', Formation = N'Động từ bỏ ます ＋ ませんか', Explanation = N'Dùng ませんか để mời hoặc đề nghị một cách lịch sự, cho người nghe cơ hội quyết định.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'won''t you ~?; why don''t we ~?' AND DATALENGTH(c.Meaning) = DATALENGTH(N'won''t you ~?; why don''t we ~?') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ ませんか' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ ませんか') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Invites someone to do something by asking a negative question: "won''t you ~?" or "why don''t we ~?". Because it is phrased negatively, it leaves the listener free to say no, so it feels softer and more considerate than a direct ましょう.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Invites someone to do something by asking a negative question: "won''t you ~?" or "why don''t we ~?". Because it is phrased negatively, it leaves the listener free to say no, so it feels softer and more considerate than a direct ましょう.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Despite the negative ません, the meaning is a positive invitation, not a literal "don''t you?".
ましょう assumes the listener will join in, while ませんか politely offers a choice.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Despite the negative ません, the meaning is a positive invitation, not a literal "don''t you?".
ましょう assumes the listener will join in, while ませんか politely offers a choice.');
SET @Parents += @@ROWCOUNT;
