AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'masen-ka:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'masen-ka:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'週末に映画を見ませんか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'週末に映画を見ませんか。')
