AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'masen-ka:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'masen-ka:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'お茶を飲みませんか。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'お茶を飲みませんか。')
