-- N5-G-021.json: mada
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'mada' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'mada');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: mada', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'まだ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'まだ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'まだ' AND DATALENGTH(c.Reading) = DATALENGTH(N'まだ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Vẫn, chưa', Formation = N'まだ ＋ câu khẳng định hoặc phủ định', Explanation = N'Với khẳng định, まだ thường chỉ trạng thái còn tiếp diễn. Với phủ định, nó có thể cho biết điều mong đợi chưa xảy ra.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'still; not yet' AND DATALENGTH(c.Meaning) = DATALENGTH(N'still; not yet') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'まだ ＋ Sentence［affirmative］
まだ ＋ Sentence［negative］' AND DATALENGTH(c.Formation) = DATALENGTH(N'まだ ＋ Sentence［affirmative］
まだ ＋ Sentence［negative］') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'まだ means "still" with an affirmative verb (a state keeps going) and "not yet" with a negative verb (something expected hasn''t happened). Either way, the situation has not moved on to the next stage.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'まだ means "still" with an affirmative verb (a state keeps going) and "not yet" with a negative verb (something expected hasn''t happened). Either way, the situation has not moved on to the next stage.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'まだ (still / not yet) is the mirror image of もう (already); learners often confuse the two.
A bare まだです can answer "not yet" on its own.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'まだ (still / not yet) is the mirror image of もう (already); learners often confuse the two.
A bare まだです can answer "not yet" on its own.');
SET @Parents += @@ROWCOUNT;
