AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'mada:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'mada:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'母はまだ寝ています。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'母はまだ寝ています。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
