AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'mada:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'mada:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'答えはまだ分かりません。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'答えはまだ分かりません。')
