-- N5-G-021.json: mada-te-imasen
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'mada-te-imasen' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'mada-te-imasen');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: mada-te-imasen', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'まだ〜ていません' AND DATALENGTH(c.Pattern) = DATALENGTH(N'まだ〜ていません') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'まだていません' AND DATALENGTH(c.Reading) = DATALENGTH(N'まだていません') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Vẫn chưa làm gì', Formation = N'まだ ＋ động từ thể て ＋ いません', Explanation = N'Dùng mẫu này để nói đến thời điểm đang xét, một việc chưa được thực hiện. まだ cũng có thể đứng sau tân ngữ như trong câu đầu.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'have not done ~ yet' AND DATALENGTH(c.Meaning) = DATALENGTH(N'have not done ~ yet') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'まだ ＋ Verb［て form］＋ いません' AND DATALENGTH(c.Formation) = DATALENGTH(N'まだ ＋ Verb［て form］＋ いません') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Says an expected action still hasn''t happened, viewed as of now: pair まだ with the negative ている form (ていません). Japanese uses the negative present here, not the past, because you are describing the current unfinished state rather than a past event.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Says an expected action still hasn''t happened, viewed as of now: pair まだ with the negative ている form (ていません). Japanese uses the negative present here, not the past, because you are describing the current unfinished state rather than a past event.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Answer with ていません, not ませんでした — ませんでした means "didn''t do it (back then)", while まだ〜ていません means "haven''t done it (but still might)".
In casual speech いません shortens to ない: まだ食べてない.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Answer with ていません, not ませんでした — ませんでした means "didn''t do it (back then)", while まだ〜ていません means "haven''t done it (but still might)".
In casual speech いません shortens to ない: まだ食べてない.');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Tôi vẫn chưa ăn trưa.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
