WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'ya' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'ya');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ya', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'や' AND DATALENGTH(c.Pattern) = DATALENGTH(N'や') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'や' AND DATALENGTH(c.Reading) = DATALENGTH(N'や') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Và những thứ như', Formation = N'Danh từ A ＋ や ＋ danh từ B（＋ など）', Explanation = N'や nêu một vài ví dụ trong danh sách còn có thể có những mục khác. Có thể thêm など để làm rõ ý liệt kê mở.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'and (such as); things like' AND DATALENGTH(c.Meaning) = DATALENGTH(N'and (such as); things like') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun ＋ や ＋ Noun
Noun ＋ や ＋ Noun ＋ など' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun ＋ や ＋ Noun
Noun ＋ や ＋ Noun ＋ など') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'や links nouns as examples from a larger set, meaning "things like A and B (among others)". Unlike と, which lists everything, や implies the list is not complete. It often finishes with など ("and so on") to make that "among others" sense explicit.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'や links nouns as examples from a larger set, meaning "things like A and B (among others)". Unlike と, which lists everything, や implies the list is not complete. It often finishes with など ("and so on") to make that "among others" sense explicit.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'や joins only nouns, and hints there are more items; と joins nouns exhaustively (exactly these).
You can add など after the last item to underline "and such".' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'や joins only nouns, and hints there are more items; と joins nouns exhaustively (exactly these).
You can add など after the last item to underline "and such".');
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Trên bàn có sách, vở và những thứ tương tự.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'ya:example:1' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'ya:example:1') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'机の上に本やノートがあります。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'机の上に本やノートがあります。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Trong tủ lạnh có trứng, sữa và những thứ khác.'
FROM GrammarExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.GrammarId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'ya:example:2' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'ya:example:2') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'冷蔵庫に卵や牛乳が入っています。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'冷蔵庫に卵や牛乳が入っています。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
