SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'yo' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'yo');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: yo', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'よ' AND DATALENGTH(c.Pattern) = DATALENGTH(N'よ') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'よ' AND DATALENGTH(c.Reading) = DATALENGTH(N'よ') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Đấy, nhé (báo tin hoặc nhấn mạnh)', Formation = N'Câu ＋ よ', Explanation = N'よ đứng cuối câu khi người nói muốn báo thông tin, lưu ý hoặc nhấn mạnh điều người nghe có thể chưa biết.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'emphasis / informing particle' AND DATALENGTH(c.Meaning) = DATALENGTH(N'emphasis / informing particle') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Sentence ＋ よ' AND DATALENGTH(c.Formation) = DATALENGTH(N'Sentence ＋ よ') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'よ at the end of a sentence tells the listener something you think they don''t already know, or drives your point home — like adding "you know" or "I''m telling you". It presents new information or reassurance from the speaker to the listener.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'よ at the end of a sentence tells the listener something you think they don''t already know, or drives your point home — like adding "you know" or "I''m telling you". It presents new information or reassurance from the speaker to the listener.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'よ presents information the speaker assumes is new; ね instead seeks the listener''s agreement about something shared.
Overusing よ can sound pushy, so save it for when you are genuinely informing or reassuring.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'よ presents information the speaker assumes is new; ね instead seeks the listener''s agreement about something shared.
Overusing よ can sound pushy, so save it for when you are genuinely informing or reassuring.');
SET @Parents += @@ROWCOUNT;
