-- N5-G-023.json: yori-hou-ga
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'yori-hou-ga' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'yori-hou-ga');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: yori-hou-ga', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'より〜のほうが' AND DATALENGTH(c.Pattern) = DATALENGTH(N'より〜のほうが') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'よりのほうが' AND DATALENGTH(c.Reading) = DATALENGTH(N'よりのほうが') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'B hơn A về một đặc điểm', Formation = N'A ＋ より ＋ B ＋ のほうが ＋ tính từ
B ＋ のほうが ＋ A ＋ より ＋ tính từ', Explanation = N'より đánh dấu mốc so sánh A. のほうが nêu phía B là phía nổi trội về đặc điểm được nói đến.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'B is more ~ than A' AND DATALENGTH(c.Meaning) = DATALENGTH(N'B is more ~ than A') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Noun-A ＋ より ＋ Noun-B ＋ のほうが ＋ い-adjective／な-adjective
Noun-B ＋ のほうが ＋ Noun-A ＋ より ＋ い-adjective／な-adjective' AND DATALENGTH(c.Formation) = DATALENGTH(N'Noun-A ＋ より ＋ Noun-B ＋ のほうが ＋ い-adjective／な-adjective
Noun-B ＋ のほうが ＋ Noun-A ＋ より ＋ い-adjective／な-adjective') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'Compares two things and states which one has more of a quality: "compared to A, B is more ~". A takes より ("than") and B takes のほうが ("the ~ side is more"). The order of the two parts is flexible, but the item marked のほうが is always the one that wins the comparison.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'Compares two things and states which one has more of a quality: "compared to A, B is more ~". A takes より ("than") and B takes のほうが ("the ~ side is more"). The order of the two parts is flexible, but the item marked のほうが is always the one that wins the comparison.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'のほうが marks the item that is "more"; より marks the baseline it beats — swap them and the meaning flips.
To pick the top out of three or more, use 一番 instead of this two-way comparison.' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'のほうが marks the item that is "more"; より marks the baseline it beats — swap them and the meaning flips.
To pick the top out of three or more, use 一番 instead of this two-way comparison.');
