-- N5-G-023.json: ru-verbs
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Grammars c JOIN GrammarSources cs ON cs.GrammarId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'Nihongo Mono Grammar' AND DATALENGTH(s.Name) = DATALENGTH(N'Nihongo Mono Grammar') AND s.Version COLLATE Latin1_General_100_BIN2 = N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25' AND DATALENGTH(s.Version) = DATALENGTH(N'ec0ba4a0ce1611c568b0e4f8a223eb8029249a25')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'ru-verbs' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'ru-verbs');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ru-verbs', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Grammars c WHERE c.Id = @Id AND c.Pattern COLLATE Latin1_General_100_BIN2 = N'る動詞' AND DATALENGTH(c.Pattern) = DATALENGTH(N'る動詞') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'るどうし' AND DATALENGTH(c.Reading) = DATALENGTH(N'るどうし') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Cách chia động từ nhóm 2', Formation = N'Gốc động từ ＋ る／ない／た／ます', Explanation = N'Với động từ nhóm 2, bỏ る cuối để lấy gốc rồi thêm đuôi cần dùng. 見る thành 見ます, còn 食べる thành 食べませんでした ở phủ định quá khứ lịch sự.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Grammars c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'ichidan (る) verb conjugation' AND DATALENGTH(c.Meaning) = DATALENGTH(N'ichidan (る) verb conjugation') AND c.Formation COLLATE Latin1_General_100_BIN2 = N'Verb［stem］＋ る ／ ない ／ た ／ ます' AND DATALENGTH(c.Formation) = DATALENGTH(N'Verb［stem］＋ る ／ ない ／ た ／ ます') AND c.Explanation COLLATE Latin1_General_100_BIN2 = N'る-verbs (ichidan verbs) are the simpler verb group: to conjugate, just drop the final る and add the ending. Their dictionary form ends in -eる or -iる, like 食べる and 見る. This one regular pattern gives the polite, negative, past, and て forms.' AND DATALENGTH(c.Explanation) = DATALENGTH(N'る-verbs (ichidan verbs) are the simpler verb group: to conjugate, just drop the final る and add the ending. Their dictionary form ends in -eる or -iる, like 食べる and 見る. This one regular pattern gives the polite, negative, past, and て forms.') AND c.UsageNotes COLLATE Latin1_General_100_BIN2 = N'Not every verb ending in る is a る-verb — 帰る and 入る look like one but conjugate as う-verbs.
Drop only the final る; don''t cut into the stem (食べる → 食べない, never 食る).' AND DATALENGTH(c.UsageNotes) = DATALENGTH(N'Not every verb ending in る is a る-verb — 帰る and 入る look like one but conjugate as う-verbs.
Drop only the final る; don''t cut into the stem (食べる → 食べない, never 食る).');
SET @Parents += @@ROWCOUNT;
