WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'fc3bc1e6f1' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'fc3bc1e6f1');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: fc3bc1e6f1', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'開く' AND DATALENGTH(c.Word) = DATALENGTH(N'開く') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'あく' AND DATALENGTH(c.Reading) = DATALENGTH(N'あく') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Mở; trở nên mở', PartOfSpeech = N'Động từ nhóm 1, tự động từ', Explanation = N'開く với cách đọc あく diễn tả cửa, cửa sổ hoặc vật tương tự mở ra. Vật mở ra thường đi với が, như ドアが開く (cửa mở ra).', UsageNotes = N'Phân biệt 開く（あく）với 開ける（あける）: ドアが開く nói cửa mở ra; ドアを開ける nói ai đó mở cửa. Chữ 開く còn có cách đọc ひらく trong những cách dùng khác.', UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to open; to become open' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to open; to become open') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'v5k, vi' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'v5k, vi') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Đẩy mạnh một cái thì cửa mở ra.'
FROM VocabularyExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.VocabularyId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Tatoeba via OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'Tatoeba via OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'225720' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'225720') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'ぐいと押すとドアは開いた。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'ぐいと押すとドアは開いた。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
