AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'2a7c4baf86' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'2a7c4baf86');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: 2a7c4baf86', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'五日' AND DATALENGTH(c.Word) = DATALENGTH(N'五日') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'いつか' AND DATALENGTH(c.Reading) = DATALENGTH(N'いつか') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Năm ngày, ngày mùng năm', PartOfSpeech = N'Danh từ chỉ thời gian', Explanation = N'五日（いつか）chỉ ngày mùng năm trong tháng hoặc khoảng thời gian năm ngày. 1月5日 là ngày mùng năm tháng Một, còn 五日待つ là chờ năm ngày.', UsageNotes = N'五日間（いつかかん）chỉ rõ khoảng thời gian năm ngày.', UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'five days; fifth day' AND DATALENGTH(c.Meaning) = DATALENGTH(N'five days; fifth day') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'n' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'n') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
