WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'ae2b9f6d7e' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'ae2b9f6d7e');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: ae2b9f6d7e', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'夕飯' AND DATALENGTH(c.Word) = DATALENGTH(N'夕飯') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'ゆうはん' AND DATALENGTH(c.Reading) = DATALENGTH(N'ゆうはん') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Bữa tối, cơm tối', PartOfSpeech = N'Danh từ', Explanation = N'夕飯（ゆうはん）chỉ bữa ăn tối. 夕飯を食べる nghĩa là ăn tối.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'dinner' AND DATALENGTH(c.Meaning) = DATALENGTH(N'dinner') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'n' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'n') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
SET @Parents += @@ROWCOUNT;
