FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to hand over' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to hand over') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'v5s, vt' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'v5s, vt') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Xin hãy đưa tôi sang bên kia sông.'
FROM VocabularyExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.VocabularyId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Tatoeba via OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'Tatoeba via OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'191763' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'191763') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'わたしを川のむこうに渡してください。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'わたしを川のむこうに渡してください。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Trong cuộc chạy tiếp sức, người chạy phải trao gậy tiếp sức.'
FROM VocabularyExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.VocabularyId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Tatoeba via OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'Tatoeba via OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'192496' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'192496') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'走者がリレーでバトンを渡さなければなりません。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'走者がリレーでバトンを渡さなければなりません。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N5-V-033.json: 78255b9860
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Vocabularies c JOIN VocabularySources cs ON cs.VocabularyId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'78255b9860' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'78255b9860');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: 78255b9860', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'渡る' AND DATALENGTH(c.Word) = DATALENGTH(N'渡る') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'わたる' AND DATALENGTH(c.Reading) = DATALENGTH(N'わたる') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Qua, băng qua, sang', PartOfSpeech = N'Động từ nhóm 1, tự động từ', Explanation = N'渡る（わたる）chỉ việc đi qua đường, cầu hoặc sông. Với tên nước, 〜へ渡る có thể diễn tả việc sang nước đó.', UsageNotes = NULL, UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'to go across' AND DATALENGTH(c.Meaning) = DATALENGTH(N'to go across') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'v5r, vi' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'v5r, vi') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Cả đoàn đã sang Mỹ.'
FROM VocabularyExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.VocabularyId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Tatoeba via OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'Tatoeba via OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'190628' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'190628') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'一行はアメリカへ渡った。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'一行はアメリカへ渡った。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Mình băng qua ở đây nhé.'
FROM VocabularyExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.VocabularyId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Tatoeba via OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'Tatoeba via OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'224241' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'224241') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'ここを渡りましょう。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'ここを渡りましょう。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
-- N5-V-033.json: 13b6dbec03
SELECT @Matches = COUNT(*), @Id = MIN(c.Id) FROM Vocabularies c JOIN VocabularySources cs ON cs.VocabularyId = c.Id
JOIN LearningContentSources s ON s.Id = cs.SourceId
WHERE s.Name COLLATE Latin1_General_100_BIN2 = N'OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND cs.ExternalId COLLATE Latin1_General_100_BIN2 = N'13b6dbec03' AND DATALENGTH(cs.ExternalId) = DATALENGTH(N'13b6dbec03');
IF @Matches > 1 THROW 51001, 'Ambiguous translation source: 13b6dbec03', 1;
IF @Matches = 1 AND EXISTS (SELECT 1 FROM Vocabularies c WHERE c.Id = @Id AND c.Word COLLATE Latin1_General_100_BIN2 = N'悪い' AND DATALENGTH(c.Word) = DATALENGTH(N'悪い') AND c.Reading COLLATE Latin1_General_100_BIN2 = N'わるい' AND DATALENGTH(c.Reading) = DATALENGTH(N'わるい') AND c.JLPTLevel COLLATE Latin1_General_100_BIN2 = N'N5' AND DATALENGTH(c.JLPTLevel) = DATALENGTH(N'N5'))
BEGIN
UPDATE c SET Meaning = N'Xấu, tệ, có lỗi', PartOfSpeech = N'Tính từ đuôi い', Explanation = N'悪い（わるい）tả điều không tốt. 人に悪いことをする có thể nói đã làm điều sai với ai đó.', UsageNotes = N'Dạng phủ định 悪くない nghĩa là không tệ.', UpdatedAt = SYSUTCDATETIME()
FROM Vocabularies c WHERE c.Id = @Id AND c.Meaning COLLATE Latin1_General_100_BIN2 = N'bad' AND DATALENGTH(c.Meaning) = DATALENGTH(N'bad') AND c.PartOfSpeech COLLATE Latin1_General_100_BIN2 = N'adj-i' AND DATALENGTH(c.PartOfSpeech) = DATALENGTH(N'adj-i') AND c.Explanation IS NULL AND c.UsageNotes IS NULL;
SET @Parents += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Chuyện này cũng đâu có tệ, phải không?'
FROM VocabularyExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.VocabularyId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Tatoeba via OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'Tatoeba via OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'74724' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'74724') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'これは悪い話ではないでしょう？' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'これは悪い話ではないでしょう？')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
UPDATE e SET VietnameseTranslation = N'Xin lỗi. Tôi đã làm điều có lỗi với bạn.'
FROM VocabularyExamples e JOIN LearningContentSources s ON s.Id = e.SourceId
WHERE e.VocabularyId = @Id AND s.Name COLLATE Latin1_General_100_BIN2 = N'Tatoeba via OpenJLPT' AND DATALENGTH(s.Name) = DATALENGTH(N'Tatoeba via OpenJLPT') AND s.Version COLLATE Latin1_General_100_BIN2 = N'0d1d3410bec90bd4098a7c72de820543cb4f707c' AND DATALENGTH(s.Version) = DATALENGTH(N'0d1d3410bec90bd4098a7c72de820543cb4f707c')
AND e.ExternalId COLLATE Latin1_General_100_BIN2 = N'215129' AND DATALENGTH(e.ExternalId) = DATALENGTH(N'215129') AND e.JapaneseText COLLATE Latin1_General_100_BIN2 = N'すいません。あなたに悪いことをしました。' AND DATALENGTH(e.JapaneseText) = DATALENGTH(N'すいません。あなたに悪いことをしました。')
AND NULLIF(LTRIM(RTRIM(e.VietnameseTranslation)), N'') IS NULL;
SET @Examples += @@ROWCOUNT;
END ELSE SET @Skipped += 1;
COMMIT;
SELECT @Parents AS ContentTranslated, @Examples AS ExamplesTranslated, @Skipped AS MissingOrChangedIdentity;
